returns uuid | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public._billing_assert_staff()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid;
  v_ok boolean := true;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Active staff session required';
  END IF;
  IF to_regprocedure('app.session_ok()') IS NOT NULL THEN
    EXECUTE 'SELECT COALESCE(app.session_ok(), false)' INTO v_ok;
    IF NOT v_ok THEN RAISE EXCEPTION 'Active staff session required'; END IF;
  END IF;
  IF COALESCE(public.my_role(), '') NOT IN ('super_admin','admin','pharmacist','billing','billing_staff') THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  v_branch := public.my_branch_id();
  IF v_branch IS NULL THEN RAISE EXCEPTION 'Staff branch not configured'; END IF;
  RETURN v_branch;
END;
$function$

returns jsonb | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public._billing_fefo_compute(p_branch uuid, p_medicine uuid, p_qty numeric, p_cart uuid, p_manual jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  m public.medicines%ROWTYPE;
  r record;
  v_today date := public.billing_today();
  v_near int := 90;
  v_req numeric := round(p_qty, 3);
  v_manual jsonb := '{}'::jsonb;
  v_manual_sum numeric := 0;
  v_seen int := 0;
  mi jsonb;
  v_avail numeric;
  v_take numeric;
  v_remaining numeric;
  v_total_avail numeric := 0;
  v_rows jsonb := '[]'::jsonb;
  v_cands jsonb := '[]'::jsonb;
  v_expired int := 0; v_blocked int := 0; v_zero int := 0; v_reserved int := 0;
  v_alloc numeric := 0;
  v_mrp numeric; v_gst numeric; v_incl boolean; v_def_disc numeric;
BEGIN
  IF v_req IS NULL OR v_req <= 0 THEN RAISE EXCEPTION 'Quantity must be greater than zero'; END IF;

  SELECT * INTO m FROM public.medicines
  WHERE id = p_medicine AND branch_id = p_branch AND active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'Medicine inactive or not found'; END IF;

  SELECT COALESCE(bs.near_expiry_days, 90) INTO v_near
  FROM public.billing_settings bs WHERE bs.branch_id = p_branch;
  v_near := COALESCE(v_near, 90);

  -- Normalise manual override into {batch_id: qty}
  IF p_manual IS NOT NULL AND jsonb_typeof(p_manual) = 'array' THEN
    FOR mi IN SELECT value FROM jsonb_array_elements(p_manual) LOOP
      IF mi->>'batch_id' IS NULL OR mi->>'qty' IS NULL OR (mi->>'qty')::numeric <= 0 THEN
        RAISE EXCEPTION 'Manual batch selection needs a batch and a positive quantity';
      END IF;
      IF v_manual ? (mi->>'batch_id') THEN
        RAISE EXCEPTION 'Duplicate batch in manual selection';
      END IF;
      v_manual := v_manual || jsonb_build_object(mi->>'batch_id', round((mi->>'qty')::numeric, 3));
      v_manual_sum := v_manual_sum + round((mi->>'qty')::numeric, 3);
    END LOOP;
    IF v_manual_sum > v_req THEN
      RAISE EXCEPTION 'Manual batch quantities (%) exceed requested quantity (%)', v_manual_sum, v_req;
    END IF;
  END IF;

  -- Exclusion statistics (explains why stock is not offered)
  SELECT
    count(*) FILTER (WHERE b.qty > 0 AND b.expiry <= v_today),
    count(*) FILTER (WHERE b.qty > 0 AND b.expiry > v_today AND (b.quarantined OR b.stock_status <> 'active')),
    count(*) FILTER (WHERE b.qty <= 0)
  INTO v_expired, v_blocked, v_zero
  FROM public.medicine_batches b
  WHERE b.branch_id = p_branch AND b.medicine_id = p_medicine;

  -- Pass 1: eligible candidates in FEFO order; apply manual quantities.
  FOR r IN
    SELECT b.*
    FROM public.medicine_batches b
    WHERE b.branch_id = p_branch
      AND b.medicine_id = p_medicine
      AND b.qty > 0
      AND b.expiry > v_today
      AND b.quarantined = false
      AND b.stock_status = 'active'
    ORDER BY b.expiry ASC, b.batch_no ASC, b.id ASC
  LOOP
    v_avail := r.qty - public._billing_reserved_by_others(r.id, p_cart);
    IF v_avail <= 0 THEN
      v_reserved := v_reserved + 1;
      IF v_manual ? r.id::text THEN
        RAISE EXCEPTION 'Batch % is fully reserved by another bill', r.batch_no;
      END IF;
      CONTINUE;
    END IF;
    v_total_avail := v_total_avail + v_avail;

    v_mrp  := COALESCE(r.mrp, NULLIF(m.mrp, 0), m.selling_price);
    v_gst  := COALESCE(r.tax_rate, m.tax_rate, 0);
    v_incl := COALESCE(r.price_includes_tax, m.price_includes_tax, true);
    v_def_disc := public.billing_default_discount_pct(m.mrp, m.selling_price, m.discount_percentage);

    v_take := 0;
    IF v_manual ? r.id::text THEN
      v_take := (v_manual->>r.id::text)::numeric;
      IF v_take > v_avail THEN
        RAISE EXCEPTION 'Batch % has only % available', r.batch_no, v_avail;
      END IF;
      v_seen := v_seen + 1;
    END IF;

    v_cands := v_cands || jsonb_build_array(jsonb_build_object(
      'batch_id', r.id, 'batch_no', r.batch_no, 'expiry', r.expiry,
      'available', v_avail, 'stock_qty', r.qty,
      'mrp', v_mrp, 'tax_rate', v_gst, 'price_includes_tax', v_incl,
      'default_discount_pct', v_def_disc,
      'days_to_expiry', (r.expiry - v_today),
      'near_expiry', (r.expiry - v_today) <= v_near,
      'manual_qty', v_take
    ));
  END LOOP;

  IF v_seen <> (SELECT count(*) FROM jsonb_object_keys(v_manual)) THEN
    RAISE EXCEPTION 'A manually selected batch is expired, blocked, recalled, empty or not in this branch';
  END IF;

  -- Pass 2: fill the remainder FEFO, emit allocation rows in expiry order.
  v_remaining := v_req - v_manual_sum;
  FOR mi IN SELECT value FROM jsonb_array_elements(v_cands) LOOP
    v_take := (mi->>'manual_qty')::numeric;
    IF v_remaining > 0 THEN
      v_avail := (mi->>'available')::numeric - v_take;
      IF v_avail > 0 THEN
        v_avail := least(v_avail, v_remaining);
        v_take := v_take + v_avail;
        v_remaining := v_remaining - v_avail;
      END IF;
    END IF;
    IF v_take > 0 THEN
      v_alloc := v_alloc + v_take;
      v_rows := v_rows || jsonb_build_array(
        (mi - 'manual_qty') || jsonb_build_object('qty', v_take, 'manual', (mi->>'manual_qty')::numeric > 0)
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'medicine_id', m.id,
    'medicine_name', m.name,
    'requested', v_req,
    'allocated', v_alloc,
    'available_total', v_total_avail,
    'shortage', greatest(v_req - v_alloc, 0),
    'rows', v_rows,
    'candidates', v_cands,
    'excluded', jsonb_build_object('expired', v_expired, 'blocked_or_recalled', v_blocked,
                                   'zero_stock', v_zero, 'fully_reserved', v_reserved),
    'manual', v_manual_sum > 0
  );
END;
$function$

returns numeric | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.adjust_stock(p_batch uuid, p_delta numeric, p_type text, p_reason text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid;
    v_batch public.medicine_batches%rowtype;
    v_new_qty numeric;
    v_movement_id bigint;
    v_needed numeric;
    v_take numeric;
    v_layer record;
    v_updated integer;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    v_branch := public.my_branch_id();

    IF v_branch IS NULL THEN
        RAISE EXCEPTION 'No active branch assigned';
    END IF;

    IF COALESCE(public.my_role(), '') NOT IN
        ('super_admin', 'admin', 'pharmacist', 'inventory') THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF p_type IS NULL OR p_type NOT IN
        ('adjustment', 'damage', 'expiry_writeoff') THEN
        RAISE EXCEPTION 'Invalid adjustment type';
    END IF;

    IF COALESCE(TRIM(p_reason), '') = '' THEN
        RAISE EXCEPTION 'A reason is required';
    END IF;

    IF p_delta IS NULL OR p_delta = 0 THEN
        RAISE EXCEPTION 'Quantity must not be zero';
    END IF;

    IF p_type <> 'adjustment' AND p_delta > 0 THEN
        RAISE EXCEPTION 'Damage and write-off must reduce stock';
    END IF;

    SELECT *
    INTO v_batch
    FROM public.medicine_batches
    WHERE id = p_batch
      AND branch_id = v_branch
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Batch not found in this branch';
    END IF;

    v_new_qty := v_batch.qty + p_delta;

    IF v_new_qty < 0 THEN
        RAISE EXCEPTION 'Stock cannot go below zero (current %)',
            v_batch.qty;
    END IF;

    UPDATE public.medicine_batches
    SET qty = v_new_qty
    WHERE id = v_batch.id
      AND branch_id = v_branch;

    INSERT INTO public.stock_movements (
        branch_id,
        medicine_id,
        batch_id,
        movement_type,
        qty,
        ref_type,
        reason,
        created_by
    )
    VALUES (
        v_branch,
        v_batch.medicine_id,
        v_batch.id,
        p_type,
        p_delta,
        'manual',
        TRIM(p_reason),
        auth.uid()
    )
    RETURNING id INTO v_movement_id;

    IF p_delta > 0 THEN
        -- Positive manual adjustment creates its own cost layer.
        INSERT INTO public.inventory_cost_layers (
            branch_id,
            medicine_id,
            batch_id,
            layer_type,
            received_qty,
            remaining_qty,
            unit_cost,
            received_at,
            source_movement_id
        )
        VALUES (
            v_branch,
            v_batch.medicine_id,
            v_batch.id,
            'adjustment',
            p_delta,
            p_delta,
            v_batch.unit_cost,
            now(),
            v_movement_id
        );

    ELSE
        -- Negative adjustment consumes existing FIFO layers.
        v_needed := ABS(p_delta);

        FOR v_layer IN
            SELECT
                l.id,
                l.remaining_qty,
                l.unit_cost
            FROM public.inventory_cost_layers l
            WHERE l.branch_id = v_branch
              AND l.medicine_id = v_batch.medicine_id
              AND l.batch_id = v_batch.id
              AND l.remaining_qty > 0
            ORDER BY
                l.received_at,
                l.created_at,
                l.id
            FOR UPDATE
        LOOP
            EXIT WHEN v_needed <= 0;

            v_take := LEAST(v_needed, v_layer.remaining_qty);

            UPDATE public.inventory_cost_layers
            SET remaining_qty = remaining_qty - v_take
            WHERE id = v_layer.id
              AND remaining_qty >= v_take;

            GET DIAGNOSTICS v_updated = ROW_COUNT;

            IF v_updated <> 1 THEN
                RAISE EXCEPTION
                    'FIFO layer changed while processing adjustment';
            END IF;

            INSERT INTO public.inventory_adjustment_allocations (
                branch_id,
                movement_id,
                cost_layer_id,
                allocation_action,
                qty,
                unit_cost
            )
            VALUES (
                v_branch,
                v_movement_id,
                v_layer.id,
                'consume',
                v_take,
                v_layer.unit_cost
            );

            v_needed := v_needed - v_take;
        END LOOP;

        IF v_needed > 0 THEN
            RAISE EXCEPTION
                'Insufficient FIFO layer quantity. Unallocated quantity: %',
                v_needed;
        END IF;
    END IF;

    INSERT INTO public.audit_logs (
        branch_id,
        user_id,
        action,
        entity_type,
        entity_id,
        reason,
        before_data,
        after_data,
        at
    )
    VALUES (
        v_branch,
        auth.uid(),
        'stock_' || p_type,
        'medicine_batch',
        v_batch.id::text,
        TRIM(p_reason),
        jsonb_build_object('qty', v_batch.qty),
        jsonb_build_object('qty', v_new_qty),
        now()
    );

    RETURN v_new_qty;
END;
$function$

returns trigger | SECURITY DEFINER | grants: PUBLIC,postgres,service_role
CREATE OR REPLACE FUNCTION public.assign_daily_invoice_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_date date;
  v_number integer;
BEGIN
  v_date := (COALESCE(NEW.created_at, now()) AT TIME ZONE 'Asia/Kolkata')::date;

  INSERT INTO public.daily_invoice_counters AS counters (invoice_date, last_value)
  VALUES (v_date, 1)
  ON CONFLICT (invoice_date)
  DO UPDATE SET last_value = counters.last_value + 1
  RETURNING last_value INTO v_number;

  NEW.invoice_no := to_char(v_date, 'YYYY-MM-DD') || '-' || lpad(v_number::text, 3, '0');
  RETURN NEW;
END;
$function$

returns jsonb | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.billing_allocate(p_cart uuid, p_medicine uuid, p_qty numeric, p_manual jsonb DEFAULT NULL::jsonb, p_override_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid;
  v_minutes int := 15;
  v_result jsonb;
  v_row jsonb;
  v_has_manual boolean;
  v_until timestamptz;
BEGIN
  v_branch := public._billing_assert_staff();
  IF p_cart IS NULL THEN RAISE EXCEPTION 'Billing session token required'; END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN RAISE EXCEPTION 'Quantity must be greater than zero'; END IF;
  IF p_qty > 100000 THEN RAISE EXCEPTION 'Quantity is too large'; END IF;

  IF EXISTS (SELECT 1 FROM public.stock_reservations
             WHERE cart_token = p_cart AND (created_by <> auth.uid() OR branch_id <> v_branch)) THEN
    RAISE EXCEPTION 'Billing session belongs to another user';
  END IF;

  v_has_manual := p_manual IS NOT NULL AND jsonb_typeof(p_manual) = 'array' AND jsonb_array_length(p_manual) > 0;
  IF v_has_manual THEN
    IF NOT public.billing_has_permission('sales.batch_override') THEN
      RAISE EXCEPTION 'You do not have permission to override batch selection';
    END IF;
    IF length(trim(COALESCE(p_override_reason, ''))) < 3 THEN
      RAISE EXCEPTION 'A reason is required for a manual batch override';
    END IF;
  END IF;

  SELECT COALESCE(reservation_minutes, 15) INTO v_minutes
  FROM public.billing_settings WHERE branch_id = v_branch;
  v_minutes := COALESCE(v_minutes, 15);
  v_until := now() + make_interval(mins => v_minutes);

  -- Serialise concurrent allocations of the same medicine.
  PERFORM 1 FROM public.medicine_batches
  WHERE branch_id = v_branch AND medicine_id = p_medicine
  ORDER BY id FOR UPDATE;

  DELETE FROM public.stock_reservations WHERE expires_at <= now();
  DELETE FROM public.stock_reservations WHERE cart_token = p_cart AND medicine_id = p_medicine;

  v_result := public._billing_fefo_compute(v_branch, p_medicine, p_qty, p_cart,
                                           CASE WHEN v_has_manual THEN p_manual ELSE NULL END);

  FOR v_row IN SELECT value FROM jsonb_array_elements(v_result->'rows') LOOP
    INSERT INTO public.stock_reservations (branch_id, cart_token, medicine_id, batch_id, qty, created_by, expires_at)
    VALUES (v_branch, p_cart, p_medicine, (v_row->>'batch_id')::uuid, (v_row->>'qty')::numeric, auth.uid(), v_until);
  END LOOP;

  -- Keep the rest of this bill's reservations alive.
  UPDATE public.stock_reservations SET expires_at = v_until WHERE cart_token = p_cart;

  IF v_has_manual THEN
    INSERT INTO public.audit_logs (branch_id, user_id, action, entity_type, entity_id, reason, before_data, after_data)
    VALUES (v_branch, auth.uid(), 'billing_batch_override', 'billing_session', p_cart::text,
            trim(p_override_reason),
            public._billing_fefo_compute(v_branch, p_medicine, p_qty, p_cart, NULL)->'rows',
            v_result->'rows');
  END IF;

  RETURN v_result || jsonb_build_object('reserved_until', v_until);
END;
$function$

returns TABLE(base_amount numeric, discount_amount numeric, taxable_amount numeric, gst_amount numeric, total_amount numeric) | grants: PUBLIC,authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.billing_calc_line(p_mrp numeric, p_qty numeric, p_discount_pct numeric, p_gst_pct numeric, p_price_includes_tax boolean)
 RETURNS TABLE(base_amount numeric, discount_amount numeric, taxable_amount numeric, gst_amount numeric, total_amount numeric)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_mrp numeric; v_qty numeric; v_d numeric; v_g numeric;
  v_base numeric; v_disc numeric; v_after numeric; v_gst numeric;
BEGIN
  IF p_mrp IS NULL OR p_mrp < 0 THEN RAISE EXCEPTION 'MRP must not be negative'; END IF;
  IF p_qty IS NULL OR p_qty <= 0 THEN RAISE EXCEPTION 'Quantity must be greater than zero'; END IF;
  IF p_discount_pct IS NULL OR p_discount_pct < 0 OR p_discount_pct > 100 THEN
    RAISE EXCEPTION 'Discount percentage must be between 0 and 100';
  END IF;
  IF p_gst_pct IS NULL OR p_gst_pct < 0 OR p_gst_pct > 40 THEN
    RAISE EXCEPTION 'GST percentage must be between 0 and 40';
  END IF;
  v_mrp := round(p_mrp, 2); v_qty := round(p_qty, 3);
  v_d := round(p_discount_pct, 2); v_g := round(p_gst_pct, 2);

  v_base  := round(v_mrp * v_qty, 2);
  v_disc  := round(v_base * v_d / 100, 2);
  v_after := v_base - v_disc;

  IF COALESCE(p_price_includes_tax, true) THEN
    v_gst := round(v_after * v_g / (100 + v_g), 2);
    RETURN QUERY SELECT v_base, v_disc, v_after - v_gst, v_gst, v_after;
  ELSE
    v_gst := round(v_after * v_g / 100, 2);
    RETURN QUERY SELECT v_base, v_disc, v_after, v_gst, v_after + v_gst;
  END IF;
END;
$function$

returns jsonb | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.billing_fefo_preview(p_medicine uuid, p_qty numeric, p_cart uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_branch uuid;
BEGIN
  v_branch := public._billing_assert_staff();
  RETURN public._billing_fefo_compute(v_branch, p_medicine, p_qty, p_cart, NULL);
END;
$function$

returns void | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.billing_log_event(p_cart uuid, p_action text, p_before jsonb, p_after jsonb, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_branch uuid;
BEGIN
  v_branch := public._billing_assert_staff();
  IF p_action NOT IN ('billing_discount_change','billing_gst_change','billing_mrp_change',
                      'billing_ai_suggestion_applied','billing_bill_cleared') THEN
    RAISE EXCEPTION 'Unsupported billing audit action';
  END IF;
  IF octet_length(COALESCE(p_before::text,'')) + octet_length(COALESCE(p_after::text,'')) > 16000 THEN
    RAISE EXCEPTION 'Audit payload too large';
  END IF;
  INSERT INTO public.audit_logs (branch_id, user_id, action, entity_type, entity_id, reason, before_data, after_data)
  VALUES (v_branch, auth.uid(), p_action, 'billing_session', p_cart::text, left(p_reason, 500), p_before, p_after);
END;
$function$

returns integer | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.billing_release(p_cart uuid, p_medicine uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Active staff session required'; END IF;
  DELETE FROM public.stock_reservations
  WHERE cart_token = p_cart AND created_by = auth.uid()
    AND (p_medicine IS NULL OR medicine_id = p_medicine);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END;
$function$

returns timestamp with time zone | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.billing_touch(p_cart uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_branch uuid; v_minutes int; v_until timestamptz;
BEGIN
  v_branch := public._billing_assert_staff();
  SELECT reservation_minutes INTO v_minutes FROM public.billing_settings WHERE branch_id = v_branch;
  v_until := now() + make_interval(mins => COALESCE(v_minutes, 15));
  UPDATE public.stock_reservations SET expires_at = v_until
  WHERE cart_token = p_cart AND created_by = auth.uid() AND expires_at > now();
  RETURN v_until;
END;
$function$

returns boolean | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.complete_password_change()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN

    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    UPDATE public.profiles
    SET
        must_change_password = false,
        updated_at = now()
    WHERE id = auth.uid()
      AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Active staff profile not found';
    END IF;

    RETURN true;

END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.confirm_purchase(p_distributor uuid, p_invoice_no text, p_date date, p_discount numeric, p_freight numeric, p_items jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    it jsonb;
    m public.medicines%rowtype;
    b public.medicine_batches%rowtype;
    inv uuid;
    v_branch uuid;
    f numeric;
    q numeric;
    pr numeric;
    tr numeric;
    ld numeric;
    net numeric;
    sub numeric := 0;
    tx numeric := 0;
    tot numeric;
    uid uuid;
    bid uuid;
    bn text;
    ex date;
begin
    v_branch := public.my_branch_id();

    if auth.uid() is null or v_branch is null then
        raise exception 'Login and active branch required';
    end if;

    if public.my_role() not in ('super_admin', 'admin', 'inventory') then
        raise exception 'Not authorised';
    end if;

    if not exists (
        select 1
        from public.distributors
        where id = p_distributor
          and branch_id = v_branch
          and active = true
    ) then
        raise exception 'Distributor missing or inactive in this branch';
    end if;

    if coalesce(trim(p_invoice_no), '') = '' then
        raise exception 'Supplier invoice number required';
    end if;

    if jsonb_typeof(p_items) <> 'array'
       or jsonb_array_length(p_items) = 0 then
        raise exception 'No purchase items';
    end if;

    if coalesce(p_discount, 0) < 0
       or coalesce(p_freight, 0) < 0 then
        raise exception 'Discount and freight cannot be negative';
    end if;

    insert into public.purchase_invoices (
        branch_id,
        distributor_id,
        supplier_invoice_no,
        invoice_date,
        discount,
        freight,
        notes,
        created_by
    )
    values (
        v_branch,
        p_distributor,
        trim(p_invoice_no),
        coalesce(p_date, current_date),
        coalesce(p_discount, 0),
        coalesce(p_freight, 0),
        p_notes,
        auth.uid()
    )
    returning id into inv;

    for it in select * from jsonb_array_elements(p_items)
    loop
        select *
        into m
        from public.medicines
        where id = (it->>'medicine_id')::uuid
          and branch_id = v_branch
          and active = true
        for update;

        if not found then
            raise exception 'Medicine not found or inactive in this branch';
        end if;

        q := (it->>'qty')::numeric;
        pr := (it->>'price')::numeric;
        tr := (it->>'tax_rate')::numeric;
        ld := coalesce((it->>'discount')::numeric, 0);

        bn := trim(coalesce(it->>'batch_no', ''));
        ex := (it->>'expiry')::date;

        if bn = '' then
            raise exception 'Batch number required for %', m.name;
        end if;

        if q is null or q <= 0
           or pr is null or pr < 0
           or tr is null or tr < 0 or tr > 40
           or ld < 0 then
            raise exception 'Invalid quantity, price, tax or discount for %', m.name;
        end if;

        if ex is null or ex <= current_date then
            raise exception 'Batch % of % is expired or has no expiry', bn, m.name;
        end if;

        uid := nullif(it->>'unit_id', '')::uuid;

        if uid is null or uid = m.base_unit_id then
            f := 1;
        else
            if m.base_unit_id is null then
                raise exception 'Set a base unit on % before buying in another unit', m.name;
            end if;

            select factor
            into f
            from public.unit_conversions
            where from_unit_id = uid
              and to_unit_id = m.base_unit_id;

            if f is null or f <= 0 then
                raise exception 'No valid unit conversion defined for %', m.name;
            end if;
        end if;

        net := round(q * pr - ld, 2);

        if net < 0 then
            raise exception 'Line discount exceeds line amount for %', m.name;
        end if;

        sub := sub + net;
        tx := tx + round(net * tr / 100, 2);

        select *
        into b
        from public.medicine_batches
        where branch_id = v_branch
          and medicine_id = m.id
          and batch_no = bn
        for update;

        if found then
            if b.expiry <> ex then
                raise exception 'Batch % already exists with a different expiry', bn;
            end if;

            update public.medicine_batches
            set qty = qty + q * f
            where id = b.id
              and branch_id = v_branch;

            bid := b.id;
        else
            insert into public.medicine_batches (
                branch_id,
                medicine_id,
                batch_no,
                expiry,
                qty,
                quarantined
            )
            values (
                v_branch,
                m.id,
                bn,
                ex,
                q * f,
                false
            )
            returning id into bid;
        end if;

        insert into public.purchase_items (
            branch_id,
            invoice_id,
            medicine_id,
            batch_id,
            qty,
            unit_id,
            unit_factor,
            base_qty,
            unit_price,
            tax_rate,
            line_discount,
            line_net
        )
        values (
            v_branch,
            inv,
            m.id,
            bid,
            q,
            uid,
            f,
            q * f,
            pr,
            tr,
            ld,
            net
        );

        insert into public.stock_movements (
            branch_id,
            medicine_id,
            batch_id,
            movement_type,
            qty,
            ref_type,
            ref_id,
            created_by
        )
        values (
            v_branch,
            m.id,
            bid,
            'purchase_in',
            q * f,
            'purchase_invoice',
            inv,
            auth.uid()
        );

        update public.medicines
        set purchase_price = round(pr / f, 2)
        where id = m.id
          and branch_id = v_branch;
    end loop;

    tot := sub + tx - coalesce(p_discount, 0) + coalesce(p_freight, 0);

    if tot < 0 then
        raise exception 'Discount exceeds invoice total';
    end if;

    update public.purchase_invoices
    set subtotal = sub,
        tax = tx,
        total = tot
    where id = inv
      and branch_id = v_branch;

    insert into public.audit_logs (
        branch_id,
        user_id,
        action,
        entity_type,
        entity_id,
        reason,
        before_data,
        after_data,
        at
    )
    values (
        v_branch,
        auth.uid(),
        'purchase_confirmed',
        'purchase_invoice',
        inv::text,
        'Purchase stock-in',
        null,
        jsonb_build_object(
            'invoice_id', inv,
            'total', tot,
            'distributor_id', p_distributor
        ),
        now()
    );

    return inv;
end;
$function$

returns jsonb | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.credit_note_detail(p_return uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid := public.my_branch_id();
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not coalesce(app.session_ok(), false) then raise exception 'An active work session is required'; end if;
  if coalesce(public.my_role(),'') not in ('super_admin','admin','pharmacist') then
    raise exception 'Not authorised';
  end if;

  select jsonb_build_object(
    'note', jsonb_build_object(
      'return_no', sr.return_no, 'created_at', sr.created_at,
      'reason', sr.reason, 'refund_method', sr.refund_method,
      'tax', sr.tax, 'total', sr.total
    ),
    'invoice_no', si.invoice_no,
    'shop', jsonb_build_object(
      'name', br.name,
      'address', concat_ws(', ', br.address, br.city, br.state, br.pincode),
      'phone', br.phone, 'gstin', br.gstin,
      'drug_licence', (select string_agg(lic.value, ', ') from jsonb_array_elements_text(br.drug_licence_nos) as lic(value))
    ),
    'customer', case when c.id is null then null
      else jsonb_build_object('name', c.name, 'phone', c.phone) end,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', m.name, 'strength', m.strength, 'batch_no', mb.batch_no,
        'qty', sri.qty, 'line_total', sri.line_total
      ) order by m.name)
      from public.sales_return_items sri
      join public.medicines m on m.id = sri.medicine_id and m.branch_id = v_branch
      join public.medicine_batches mb on mb.id = sri.batch_id and mb.branch_id = v_branch
      where sri.return_id = sr.id and sri.branch_id = v_branch
    ), '[]'::jsonb)
  ) into v_result
  from public.sales_returns sr
  join public.sales_invoices si on si.id = sr.invoice_id and si.branch_id = v_branch
  left join public.customers c on c.id = sr.customer_id and c.branch_id = v_branch
  join public.branches br on br.id = sr.branch_id
  where sr.id = p_return and sr.branch_id = v_branch;

  if v_result is null then raise exception 'Credit note not found'; end if;
  return v_result;
end;
$function$

returns trigger | grants: PUBLIC,postgres,service_role
CREATE OR REPLACE FUNCTION public.customers_norm()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare p text := regexp_replace(coalesce(new.phone,''),'[^0-9+]','','g');
begin
  if p ~ '^[0-9]{10}$' then p := '+91'||p;
  elsif p ~ '^91[0-9]{10}$' then p := '+'||p; end if;
  new.phone := p;
  if new.consent and (tg_op='INSERT' or not old.consent) then new.consent_at := now(); end if;
  if not new.consent then new.consent_at := null; end if;
  return new;
end $function$

returns text | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.delete_medicine_image(p_image uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid;
  v_image record;
begin
  v_branch := public.my_branch_id();

  if auth.uid() is null or v_branch is null then
    raise exception 'Login and active branch required';
  end if;

  if public.my_role() not in
    ('super_admin','admin','pharmacist','inventory') then
    raise exception 'Not authorised';
  end if;

  select * into v_image
  from medicine_images
  where id = p_image
    and branch_id = v_branch
  for update;

  if not found then
    raise exception 'Image not found';
  end if;

  delete from medicine_images
  where id = p_image
    and branch_id = v_branch;

  if v_image.is_primary then
    update medicine_images
    set is_primary = true
    where id = (
      select id
      from medicine_images
      where medicine_id = v_image.medicine_id
        and branch_id = v_branch
      order by sort_order,created_at
      limit 1
    );
  end if;

  insert into audit_logs (
    branch_id,user_id,action,entity_type,entity_id,
    before_data,at
  )
  values (
    v_branch,auth.uid(),'medicine_image_deleted',
    'medicine_image',p_image::text,
    jsonb_build_object('path',v_image.path),
    now()
  );

  return v_image.path;
end;
$function$

returns void | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.delivery_assign(p_invoice_id uuid, p_delivery_person_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid := public.my_branch_id();
  v_role text := public.my_role();
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL OR v_role IS NULL THEN
    RAISE EXCEPTION 'Login with an active branch profile is required';
  END IF;
  IF v_role NOT IN ('super_admin','admin','admin_staff','pharmacist','billing_staff','billing') THEN
    RAISE EXCEPTION 'Not authorised to assign deliveries';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p JOIN public.roles r ON r.id = p.role_id
    WHERE p.id = p_delivery_person_id AND p.branch_id = v_branch
      AND p.is_active = true AND r.code = 'delivery_person'
  ) THEN RAISE EXCEPTION 'Active delivery-person account not found in this branch'; END IF;

  UPDATE public.delivery_jobs
  SET assigned_to = p_delivery_person_id, assigned_by = auth.uid(), assigned_at = now(),
      status = 'pending', updated_by = auth.uid(), updated_at = now()
  WHERE branch_id = v_branch AND invoice_id = p_invoice_id AND is_requested = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'Mark this invoice as delivery requested before assigning it'; END IF;

  INSERT INTO public.audit_logs(branch_id,user_id,action,entity_type,entity_id,after_data,at)
  VALUES (v_branch,auth.uid(),'delivery_assigned','sales_invoice',p_invoice_id::text,
          jsonb_build_object('delivery_person_id',p_delivery_person_id),now());
END;
$function$

returns jsonb | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.delivery_management_list()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid := public.my_branch_id();
  v_role text := public.my_role();
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL OR v_role IS NULL THEN
    RAISE EXCEPTION 'Login with an active branch profile is required';
  END IF;
  IF v_role NOT IN ('super_admin','admin','admin_staff','pharmacist','billing_staff','billing') THEN
    RAISE EXCEPTION 'Not authorised to manage deliveries';
  END IF;

  SELECT jsonb_build_object(
    'invoices', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id,
        'branch_id', i.branch_id,
        'invoice_no', i.invoice_no,
        'customer_id', i.customer_id,
        'total', i.total,
        'status', i.status,
        'created_at', i.created_at,
        'customer', CASE WHEN c.id IS NULL THEN NULL ELSE jsonb_build_object(
          'id', c.id, 'name', c.name, 'phone', c.phone, 'address', c.address
        ) END,
        'delivery', CASE WHEN d.id IS NULL THEN NULL ELSE jsonb_build_object(
          'id', d.id, 'is_requested', d.is_requested, 'assigned_to', d.assigned_to,
          'status', d.status, 'requested_at', d.requested_at, 'assigned_at', d.assigned_at
        ) END,
        'delivery_person', CASE WHEN p.id IS NULL THEN NULL ELSE jsonb_build_object(
          'id', p.id, 'staff_id', p.staff_id, 'full_name', p.full_name, 'phone', p.phone
        ) END
      ) ORDER BY i.created_at DESC)
      FROM public.sales_invoices i
      LEFT JOIN public.customers c ON c.id = i.customer_id AND c.branch_id = v_branch
      LEFT JOIN public.delivery_jobs d ON d.invoice_id = i.id AND d.branch_id = v_branch
      LEFT JOIN public.profiles p ON p.id = d.assigned_to AND p.branch_id = v_branch
      WHERE i.branch_id = v_branch AND i.status = 'final'
    ), '[]'::jsonb),
    'delivery_people', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', p.id, 'staff_id', p.staff_id, 'full_name', p.full_name, 'phone', p.phone
      ) ORDER BY p.full_name)
      FROM public.profiles p
      JOIN public.roles r ON r.id = p.role_id
      WHERE p.branch_id = v_branch AND p.is_active = true AND r.code = 'delivery_person'
    ), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$

returns jsonb | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.delivery_my_jobs()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid := public.my_branch_id();
  v_role text := public.my_role();
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL OR v_role <> 'delivery_person' THEN
    RAISE EXCEPTION 'Delivery-person login is required';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', i.id, 'invoice_no', i.invoice_no, 'total', i.total, 'created_at', i.created_at,
    'customer', jsonb_build_object('name', c.name, 'phone', c.phone, 'address', c.address),
    'status', d.status, 'updated_at', d.updated_at
  ) ORDER BY d.assigned_at DESC), '[]'::jsonb)
  INTO v_result
  FROM public.delivery_jobs d
  JOIN public.sales_invoices i ON i.id = d.invoice_id AND i.branch_id = v_branch
  LEFT JOIN public.customers c ON c.id = i.customer_id AND c.branch_id = v_branch
  WHERE d.branch_id = v_branch AND d.assigned_to = auth.uid() AND d.is_requested = true;
  RETURN v_result;
END;
$function$

returns void | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.delivery_set_request(p_invoice_id uuid, p_requested boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid := public.my_branch_id();
  v_role text := public.my_role();
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL OR v_role IS NULL THEN
    RAISE EXCEPTION 'Login with an active branch profile is required';
  END IF;
  IF v_role NOT IN ('super_admin','admin','admin_staff','pharmacist','billing_staff','billing') THEN
    RAISE EXCEPTION 'Not authorised to update delivery requests';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.sales_invoices WHERE id = p_invoice_id AND branch_id = v_branch AND status = 'final') THEN
    RAISE EXCEPTION 'Final invoice not found in this branch';
  END IF;

  INSERT INTO public.delivery_jobs(branch_id, invoice_id, is_requested, requested_by, requested_at, updated_by, updated_at)
  VALUES (v_branch, p_invoice_id, COALESCE(p_requested,false), CASE WHEN p_requested THEN auth.uid() END,
          CASE WHEN p_requested THEN now() END, auth.uid(), now())
  ON CONFLICT (branch_id, invoice_id) DO UPDATE SET
    is_requested = EXCLUDED.is_requested,
    requested_by = CASE WHEN EXCLUDED.is_requested THEN auth.uid() ELSE delivery_jobs.requested_by END,
    requested_at = CASE WHEN EXCLUDED.is_requested THEN now() ELSE delivery_jobs.requested_at END,
    assigned_to = CASE WHEN EXCLUDED.is_requested THEN delivery_jobs.assigned_to ELSE NULL END,
    assigned_by = CASE WHEN EXCLUDED.is_requested THEN delivery_jobs.assigned_by ELSE NULL END,
    status = CASE WHEN EXCLUDED.is_requested THEN delivery_jobs.status ELSE 'pending' END,
    updated_by = auth.uid(), updated_at = now();

  INSERT INTO public.audit_logs(branch_id,user_id,action,entity_type,entity_id,after_data,at)
  VALUES (v_branch,auth.uid(),CASE WHEN p_requested THEN 'delivery_requested' ELSE 'delivery_request_removed' END,
          'sales_invoice',p_invoice_id::text,jsonb_build_object('is_requested',p_requested),now());
END;
$function$

returns void | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.delivery_update_status(p_invoice_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid := public.my_branch_id();
  v_role text := public.my_role();
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL OR v_role <> 'delivery_person' THEN
    RAISE EXCEPTION 'Delivery-person login is required';
  END IF;
  IF p_status NOT IN ('out','done') THEN RAISE EXCEPTION 'Unsupported delivery status'; END IF;

  UPDATE public.delivery_jobs
  SET status = p_status, updated_by = auth.uid(), updated_at = now()
  WHERE branch_id = v_branch AND invoice_id = p_invoice_id
    AND assigned_to = auth.uid() AND is_requested = true
    AND ((p_status = 'out' AND status = 'pending') OR (p_status = 'done' AND status = 'out'));
  IF NOT FOUND THEN RAISE EXCEPTION 'This delivery is not assigned to you or the requested status transition is not allowed'; END IF;

  INSERT INTO public.audit_logs(branch_id,user_id,action,entity_type,entity_id,after_data,at)
  VALUES (v_branch,auth.uid(),'delivery_status_updated','sales_invoice',p_invoice_id::text,
          jsonb_build_object('status',p_status),now());
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.expense_category_add(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_id uuid;
    v_name text := trim(coalesce(p_name,''));
BEGIN
    IF auth.uid() IS NULL OR v_branch IS NULL THEN
        RAISE EXCEPTION 'Login and active branch required';
    END IF;

    IF coalesce(public.my_role(),'')
       NOT IN ('admin','super_admin') THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF NOT coalesce(app.session_ok(),false) THEN
        RAISE EXCEPTION 'An active work session is required';
    END IF;

    IF length(v_name) < 2 OR length(v_name) > 60 THEN
        RAISE EXCEPTION 'Category name must be 2 to 60 characters';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.expense_categories c
        WHERE c.branch_id = v_branch
          AND lower(trim(c.name)) = lower(v_name)
    ) THEN
        RAISE EXCEPTION 'This category already exists in your branch';
    END IF;

    INSERT INTO public.expense_categories (
        branch_id,
        name,
        active,
        created_by
    )
    VALUES (
        v_branch,
        v_name,
        true,
        auth.uid()
    )
    RETURNING id INTO v_id;

    INSERT INTO public.audit_logs (
        branch_id, user_id, action, entity_type,
        entity_id, after_data, at
    )
    VALUES (
        v_branch, auth.uid(), 'expense_category_created',
        'expense_category', v_id::text,
        jsonb_build_object('name',v_name,'active',true),
        now()
    );

    RETURN v_id;
END;
$function$

returns boolean | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.expense_category_deactivate(p_category_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_name text;
BEGIN
    IF auth.uid() IS NULL OR v_branch IS NULL THEN
        RAISE EXCEPTION 'Login and active branch required';
    END IF;

    IF coalesce(public.my_role(),'')
       NOT IN ('admin','super_admin') THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF NOT coalesce(app.session_ok(),false) THEN
        RAISE EXCEPTION 'An active work session is required';
    END IF;

    SELECT name
    INTO v_name
    FROM public.expense_categories
    WHERE id = p_category_id
      AND branch_id = v_branch
      AND active = true
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Active branch category not found; shared categories cannot be deactivated';
    END IF;

    UPDATE public.expense_categories
    SET active = false
    WHERE id = p_category_id
      AND branch_id = v_branch;

    INSERT INTO public.audit_logs (
        branch_id, user_id, action, entity_type,
        entity_id, reason, before_data, after_data, at
    )
    VALUES (
        v_branch, auth.uid(), 'expense_category_deactivated',
        'expense_category', p_category_id::text,
        'Category deactivated',
        jsonb_build_object('name',v_name,'active',true),
        jsonb_build_object('name',v_name,'active',false),
        now()
    );

    RETURN true;
END;
$function$

returns boolean | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.expense_category_reactivate(p_category_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_name text;
BEGIN
    IF auth.uid() IS NULL OR v_branch IS NULL THEN
        RAISE EXCEPTION 'Login and active branch required';
    END IF;

    IF coalesce(public.my_role(),'')
       NOT IN ('admin','super_admin') THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF NOT coalesce(app.session_ok(),false) THEN
        RAISE EXCEPTION 'An active work session is required';
    END IF;

    SELECT name
    INTO v_name
    FROM public.expense_categories
    WHERE id = p_category_id
      AND branch_id = v_branch
      AND active = false
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Inactive branch category not found; shared categories cannot be changed';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.expense_categories
        WHERE branch_id = v_branch
          AND id <> p_category_id
          AND lower(trim(name)) = lower(trim(v_name))
    ) THEN
        RAISE EXCEPTION 'Another category already uses this name';
    END IF;

    UPDATE public.expense_categories
    SET active = true
    WHERE id = p_category_id
      AND branch_id = v_branch;

    INSERT INTO public.audit_logs (
        branch_id, user_id, action, entity_type,
        entity_id, reason, before_data, after_data, at
    )
    VALUES (
        v_branch, auth.uid(), 'expense_category_reactivated',
        'expense_category', p_category_id::text,
        'Category reactivated',
        jsonb_build_object('name',v_name,'active',false),
        jsonb_build_object('name',v_name,'active',true),
        now()
    );

    RETURN true;
END;
$function$

returns boolean | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.expense_category_rename(p_category_id uuid, p_new_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_name text := trim(coalesce(p_new_name,''));
    v_old_name text;
BEGIN
    IF auth.uid() IS NULL OR v_branch IS NULL THEN
        RAISE EXCEPTION 'Login and active branch required';
    END IF;

    IF coalesce(public.my_role(),'')
       NOT IN ('admin','super_admin') THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF NOT coalesce(app.session_ok(),false) THEN
        RAISE EXCEPTION 'An active work session is required';
    END IF;

    IF length(v_name) < 2 OR length(v_name) > 60 THEN
        RAISE EXCEPTION 'Category name must be 2 to 60 characters';
    END IF;

    SELECT name
    INTO v_old_name
    FROM public.expense_categories
    WHERE id = p_category_id
      AND branch_id = v_branch
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Branch category not found; shared categories cannot be renamed';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.expense_categories
        WHERE branch_id = v_branch
          AND id <> p_category_id
          AND lower(trim(name)) = lower(v_name)
    ) THEN
        RAISE EXCEPTION 'This category name already exists in your branch';
    END IF;

    UPDATE public.expense_categories
    SET name = v_name
    WHERE id = p_category_id
      AND branch_id = v_branch;

    INSERT INTO public.audit_logs (
        branch_id, user_id, action, entity_type,
        entity_id, reason, before_data, after_data, at
    )
    VALUES (
        v_branch, auth.uid(), 'expense_category_renamed',
        'expense_category', p_category_id::text,
        'Category renamed',
        jsonb_build_object('name',v_old_name),
        jsonb_build_object('name',v_name),
        now()
    );

    RETURN true;
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.expense_register_receipt(p_expense_id uuid, p_storage_path text, p_file_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_expense public.expenses%rowtype;
    v_object record;
    v_id uuid;
    v_size bigint;
    v_mime text;
BEGIN
    IF auth.uid() IS NULL OR v_branch IS NULL THEN
        RAISE EXCEPTION 'Login and active branch required';
    END IF;

    IF coalesce(public.my_role(),'')
       NOT IN ('admin','super_admin') THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF NOT coalesce(app.session_ok(),false) THEN
        RAISE EXCEPTION 'An active work session is required';
    END IF;

    SELECT *
    INTO v_expense
    FROM public.expenses
    WHERE id = p_expense_id
      AND branch_id = v_branch
    FOR UPDATE;

    IF NOT FOUND OR v_expense.status = 'cancelled' THEN
        RAISE EXCEPTION 'Expense not found or cancelled';
    END IF;

    IF p_storage_path !~
       ('^' || p_expense_id::text ||
        '/[0-9a-f-]{36}\.(pdf|jpg|jpeg|png|webp)$') THEN
        RAISE EXCEPTION 'Invalid receipt storage path';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.expense_receipts
        WHERE storage_path = p_storage_path
    ) THEN
        RAISE EXCEPTION 'Receipt is already registered';
    END IF;

    SELECT o.metadata
    INTO v_object
    FROM storage.objects o
    WHERE o.bucket_id = 'expense-receipts'
      AND o.name = p_storage_path;

    IF NOT FOUND OR v_object.metadata IS NULL THEN
        RAISE EXCEPTION 'Uploaded receipt not found';
    END IF;

    v_size := (v_object.metadata->>'size')::bigint;
    v_mime := lower(v_object.metadata->>'mimetype');

    IF v_size IS NULL OR v_size <= 0
       OR v_size > 15728640 THEN
        RAISE EXCEPTION 'Invalid receipt file size';
    END IF;

    IF v_mime NOT IN (
        'application/pdf',
        'image/jpeg',
        'image/png',
        'image/webp'
    ) THEN
        RAISE EXCEPTION 'Unsupported receipt file type';
    END IF;

    INSERT INTO public.expense_receipts (
        branch_id,
        expense_id,
        storage_path,
        file_name,
        mime_type,
        file_size,
        uploaded_by
    )
    VALUES (
        v_branch,
        p_expense_id,
        p_storage_path,
        trim(p_file_name),
        v_mime,
        v_size,
        auth.uid()
    )
    RETURNING id INTO v_id;

    INSERT INTO public.audit_logs (
        branch_id,user_id,action,entity_type,
        entity_id,reason,after_data,at
    )
    VALUES (
        v_branch,auth.uid(),'expense_receipt_uploaded',
        'expense',p_expense_id::text,
        'Expense receipt registered',
        jsonb_build_object(
            'receipt_id',v_id,
            'file_name',trim(p_file_name),
            'mime_type',v_mime,
            'file_size',v_size
        ),
        now()
    );

    RETURN v_id;
END;
$function$

returns trigger | SECURITY DEFINER | grants: PUBLIC,postgres,service_role
CREATE OR REPLACE FUNCTION public.fifo_create_purchase_layer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_unit_cost numeric;
BEGIN
    IF NEW.base_qty IS NULL OR NEW.base_qty <= 0 THEN
        RAISE EXCEPTION 'Invalid purchase base quantity';
    END IF;

    v_unit_cost := ROUND(NEW.line_net / NEW.base_qty, 6);

    INSERT INTO public.inventory_cost_layers (
        branch_id, medicine_id, batch_id, purchase_item_id,
        layer_type, received_qty, remaining_qty, unit_cost, received_at
    )
    VALUES (
        NEW.branch_id, NEW.medicine_id, NEW.batch_id, NEW.id,
        'paid', NEW.base_qty, NEW.base_qty, v_unit_cost, now()
    )
    ON CONFLICT (purchase_item_id, layer_type)
    WHERE purchase_item_id IS NOT NULL
    DO NOTHING;

    RETURN NEW;
END;
$function$

returns uuid | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public.finalize_sale(p_customer uuid, p_items jsonb, p_payments jsonb, p_discount numeric DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$

DECLARE

    it jsonb;
    pm jsonb;

    b public.medicine_batches%ROWTYPE;
    m public.medicines%ROWTYPE;

    inv uuid;
    v_branch uuid;
    v_prefix text;

    sub numeric := 0;
    tx numeric := 0;
    tot numeric;
    paid numeric := 0;
    lt numeric;

    v_qty numeric;
    v_amount numeric;
    v_discount numeric;
    v_credit_due numeric := 0;
    v_outstanding numeric := 0;
    v_customer public.customers%ROWTYPE;

BEGIN

    -- Require an authenticated, active staff session.
    IF auth.uid() IS NULL OR NOT COALESCE(app.session_ok(), false) THEN
        RAISE EXCEPTION 'Active staff session required';
    END IF;

    -- Staff authorization

    IF COALESCE(public.my_role(), '') NOT IN (
        'super_admin',
        'admin',
        'pharmacist',
        'billing',
        'billing_staff'
    ) THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;


    -- Staff branch

    v_branch := public.my_branch_id();

    IF v_branch IS NULL THEN
        RAISE EXCEPTION 'Staff branch not configured';
    END IF;


    -- Validate cart

    IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Invalid cart';
    END IF;

    IF jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Empty cart';
    END IF;


    -- Validate payments

    IF jsonb_typeof(p_payments) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Invalid payment data';
    END IF;


    IF p_discount IS NULL OR p_discount < 0 THEN
        RAISE EXCEPTION 'Invalid discount';
    END IF;

    v_discount := round(p_discount, 2);

    IF v_discount > 0 AND NOT EXISTS (
        SELECT 1
        FROM public.profiles pr
        JOIN public.role_permissions rp ON rp.role_id = pr.role_id
        WHERE pr.id = auth.uid()
          AND pr.branch_id = v_branch
          AND pr.is_active = true
          AND rp.permission_code = 'sales.discount'
    ) THEN
        RAISE EXCEPTION 'You do not have permission to apply discounts';
    END IF;


    -- Lock the customer row so concurrent bills cannot exceed the credit limit.
    IF p_customer IS NOT NULL THEN
        SELECT * INTO v_customer
        FROM public.customers
        WHERE id = p_customer
          AND branch_id = v_branch
          AND active = true
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Customer not found or inactive in this branch';
        END IF;
    END IF;


    -- Branch invoice prefix

    SELECT COALESCE(NULLIF(invoice_prefix, ''), 'ALZA')
    INTO v_prefix
    FROM public.branches
    WHERE id = v_branch
      AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Branch inactive or not found';
    END IF;


    -- Create invoice

    INSERT INTO public.sales_invoices (
        branch_id,
        invoice_no,
        customer_id,
        subtotal,
        discount,
        tax,
        total,
        status,
        created_by
    )
    VALUES (
        v_branch,
        v_prefix || '-' ||
        to_char(now() AT TIME ZONE 'Asia/Kolkata', 'YYMM') ||
        '-' ||
        lpad(nextval('public.invoice_seq'::regclass)::text, 6, '0'),
        p_customer,
        0,
        v_discount,
        0,
        0,
        'final',
        auth.uid()
    )
    RETURNING id INTO inv;


    -- Process each cart item

    FOR it IN
        SELECT value
        FROM jsonb_array_elements(p_items)
    LOOP

        IF it->>'batch_id' IS NULL
           OR it->>'qty' IS NULL THEN
            RAISE EXCEPTION 'Missing batch or quantity';
        END IF;

        v_qty := round((it->>'qty')::numeric, 3);

        IF v_qty <= 0 THEN
            RAISE EXCEPTION 'Invalid quantity';
        END IF;


        -- Lock branch batch

        SELECT *
        INTO b
        FROM public.medicine_batches
        WHERE id = (it->>'batch_id')::uuid
          AND branch_id = v_branch
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Batch not found in this branch';
        END IF;


        -- Expiry check

        IF b.expiry <= current_date THEN
            RAISE EXCEPTION 'Batch % expired', b.batch_no;
        END IF;


        -- Quarantine check

        IF b.quarantined THEN
            RAISE EXCEPTION 'Batch % quarantined', b.batch_no;
        END IF;


        -- Stock check

        IF b.qty < v_qty THEN
            RAISE EXCEPTION 'Insufficient stock: %', b.batch_no;
        END IF;


        -- Medicine validation

        SELECT *
        INTO m
        FROM public.medicines
        WHERE id = b.medicine_id
          AND branch_id = v_branch
          AND active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Medicine inactive or not found';
        END IF;


        -- Calculate line total

        lt := round(m.selling_price * v_qty, 2);

        sub := sub + lt;

        -- Tax included in selling price

        tx := tx + round(
            lt * m.tax_rate / (100 + m.tax_rate),
            2
        );


        -- Deduct stock

        UPDATE public.medicine_batches
        SET qty = qty - v_qty
        WHERE id = b.id;


        -- Record sale item

        INSERT INTO public.sales_items (
            branch_id,
            invoice_id,
            medicine_id,
            batch_id,
            qty,
            unit_price,
            tax_rate,
            line_total
        )
        VALUES (
            v_branch,
            inv,
            m.id,
            b.id,
            v_qty,
            m.selling_price,
            m.tax_rate,
            lt
        );

    END LOOP;


    -- Calculate total

    tot := round(sub - v_discount, 2);

    IF tot < 0 THEN
        RAISE EXCEPTION 'Discount exceeds total';
    END IF;


    -- Record actual tendered payments only. The unpaid remainder is
    -- generated below as a credit row, never supplied by the browser.
    FOR pm IN
        SELECT value
        FROM jsonb_array_elements(p_payments)
    LOOP
        IF COALESCE(pm->>'method', '') NOT IN ('cash', 'upi', 'card') THEN
            RAISE EXCEPTION 'Invalid payment method';
        END IF;

        IF pm->>'amount' IS NULL THEN
            RAISE EXCEPTION 'Missing payment amount';
        END IF;

        v_amount := round((pm->>'amount')::numeric, 2);

        IF v_amount <= 0 THEN
            RAISE EXCEPTION 'Invalid payment amount';
        END IF;

        paid := round(paid + v_amount, 2);

        IF paid > tot THEN
            RAISE EXCEPTION 'Payments (%) exceed invoice total (%)', paid, tot;
        END IF;

        INSERT INTO public.payments (
            branch_id, invoice_id, method, amount
        ) VALUES (
            v_branch, inv, pm->>'method', v_amount
        );
    END LOOP;

    -- Create customer receivable for the unpaid remainder.
    v_credit_due := round(tot - paid, 2);

    IF v_credit_due < 0 THEN
        RAISE EXCEPTION 'Payments cannot exceed invoice total';
    END IF;

    IF v_credit_due > 0 THEN
        IF p_customer IS NULL THEN
            RAISE EXCEPTION 'An active customer is required for an unpaid balance';
        END IF;

        -- Customer row was locked above to serialize concurrent credit sales.
        v_outstanding := public.customer_outstanding(p_customer);

        IF round(v_outstanding + v_credit_due, 2) > v_customer.credit_limit THEN
            RAISE EXCEPTION
                'Customer credit limit exceeded. Available: %',
                greatest(0, round(v_customer.credit_limit - v_outstanding, 2));
        END IF;

        INSERT INTO public.payments (
            branch_id, invoice_id, method, amount
        ) VALUES (
            v_branch, inv, 'credit', v_credit_due
        );
    END IF;

    -- All payment rows (including generated credit) must equal invoice total.
    IF round(paid + v_credit_due, 2) <> tot THEN
        RAISE EXCEPTION 'Payment allocation does not equal invoice total';
    END IF;


    -- Update invoice

    UPDATE public.sales_invoices
    SET
        subtotal = sub,
        tax = tx,
        total = tot
    WHERE id = inv;


    -- Existing audit log structure

    INSERT INTO public.audit_logs (
        branch_id,
        user_id,
        action,
        entity_type,
        entity_id,
        reason,
        before_data,
        after_data
    )
    VALUES (
        v_branch,
        auth.uid(),
        'sale_finalized',
        'sales_invoice',
        inv::text,
        'POS sale completed',
        NULL,
        jsonb_build_object(
            'invoice_id', inv,
            'invoice_total', tot,
            'subtotal', sub,
            'tax', tx,
            'discount', v_discount
        )
    );


    RETURN inv;

END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.finalize_sale_v2(p_customer uuid, p_items jsonb, p_payments jsonb, p_discount numeric DEFAULT 0, p_cart uuid DEFAULT NULL::uuid, p_expected_total numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  it jsonb; pm jsonb;
  b public.medicine_batches%ROWTYPE;
  m public.medicines%ROWTYPE;
  c record;
  inv uuid; v_branch uuid; v_prefix text;
  v_today date := public.billing_today();
  v_max_disc numeric := 30;

  sub numeric := 0; tx numeric := 0; v_line_disc numeric := 0; v_taxable numeric := 0;
  tot numeric; paid numeric := 0;
  v_qty numeric; v_amount numeric; v_discount numeric;
  v_credit_due numeric := 0; v_outstanding numeric := 0;
  v_customer public.customers%ROWTYPE;

  v_def_mrp numeric; v_def_disc numeric; v_def_gst numeric; v_incl boolean;
  v_mrp numeric; v_disc numeric; v_gst numeric; v_manual boolean;
  v_avail numeric;
  v_calc record;
  v_changes jsonb := '[]'::jsonb;
  v_expected jsonb; v_submitted jsonb;
  v_med uuid;
BEGIN
  v_branch := public._billing_assert_staff();

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid cart'; END IF;
  IF jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'Empty cart'; END IF;
  IF jsonb_array_length(p_items) > 300 THEN RAISE EXCEPTION 'Too many bill lines'; END IF;
  IF jsonb_typeof(p_payments) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid payment data'; END IF;
  IF p_discount IS NULL OR p_discount < 0 THEN RAISE EXCEPTION 'Invalid discount'; END IF;
  v_discount := round(p_discount, 2);
  IF v_discount > 0 AND NOT public.billing_has_permission('sales.discount') THEN
    RAISE EXCEPTION 'You do not have permission to apply discounts';
  END IF;

  SELECT COALESCE(max_discount_pct, 30) INTO v_max_disc FROM public.billing_settings WHERE branch_id = v_branch;
  v_max_disc := COALESCE(v_max_disc, 30);

  -- Structural validation: required fields, no duplicate batch allocations.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_items) e
             WHERE e.value->>'batch_id' IS NULL OR e.value->>'qty' IS NULL) THEN
    RAISE EXCEPTION 'Missing batch or quantity';
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_items))
     <> (SELECT count(DISTINCT e.value->>'batch_id') FROM jsonb_array_elements(p_items) e) THEN
    RAISE EXCEPTION 'Duplicate batch allocation in bill';
  END IF;

  -- Lock every batch of every medicine on the bill, in id order (deadlock safe,
  -- same order as billing_allocate()).
  PERFORM 1 FROM public.medicine_batches
  WHERE branch_id = v_branch
    AND medicine_id IN (SELECT mb.medicine_id FROM public.medicine_batches mb
                        WHERE mb.id IN (SELECT (e.value->>'batch_id')::uuid FROM jsonb_array_elements(p_items) e))
  ORDER BY id FOR UPDATE;

  -- FEFO verification for medicines that were not manually overridden.
  FOR c IN
    SELECT mb.medicine_id,
           sum(round((e.value->>'qty')::numeric, 3)) AS total_qty,
           bool_or(COALESCE((e.value->>'manual')::boolean, false)) AS any_manual,
           jsonb_object_agg(e.value->>'batch_id', round((e.value->>'qty')::numeric, 3)) AS submitted
    FROM jsonb_array_elements(p_items) e
    JOIN public.medicine_batches mb ON mb.id = (e.value->>'batch_id')::uuid AND mb.branch_id = v_branch
    GROUP BY mb.medicine_id
  LOOP
    IF c.any_manual THEN
      IF NOT public.billing_has_permission('sales.batch_override') THEN
        RAISE EXCEPTION 'You do not have permission to override batch selection';
      END IF;
      CONTINUE;
    END IF;
    v_expected := public._billing_fefo_compute(v_branch, c.medicine_id, c.total_qty, p_cart, NULL);
    IF (v_expected->>'shortage')::numeric > 0 THEN
      RAISE EXCEPTION 'Insufficient stock for %: requested %, available %',
        v_expected->>'medicine_name', c.total_qty, v_expected->>'available_total';
    END IF;
    SELECT COALESCE(jsonb_object_agg(r.value->>'batch_id', (r.value->>'qty')::numeric), '{}'::jsonb)
      INTO v_submitted FROM jsonb_array_elements(v_expected->'rows') r;
    IF v_submitted <> c.submitted THEN
      RAISE EXCEPTION 'Stock changed for % since it was allocated. Re-enter the quantity to re-allocate (FEFO).',
        v_expected->>'medicine_name';
    END IF;
  END LOOP;

  IF p_customer IS NOT NULL THEN
    SELECT * INTO v_customer FROM public.customers
    WHERE id = p_customer AND branch_id = v_branch AND active = true
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found or inactive in this branch'; END IF;
  END IF;

  SELECT COALESCE(NULLIF(invoice_prefix, ''), 'ALZA') INTO v_prefix
  FROM public.branches WHERE id = v_branch AND is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'Branch inactive or not found'; END IF;

  -- invoice_no is replaced by trg_assign_daily_invoice_number (0019).
  INSERT INTO public.sales_invoices (branch_id, invoice_no, customer_id, subtotal, discount, tax, total, status, created_by)
  VALUES (v_branch,
          v_prefix || '-' || to_char(now() AT TIME ZONE 'Asia/Kolkata', 'YYMM') || '-' ||
            lpad(nextval('public.invoice_seq'::regclass)::text, 6, '0'),
          p_customer, 0, v_discount, 0, 0, 'final', auth.uid())
  RETURNING id INTO inv;

  FOR it IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_qty := round((it->>'qty')::numeric, 3);
    IF v_qty <= 0 THEN RAISE EXCEPTION 'Quantity must be greater than zero'; END IF;

    SELECT * INTO b FROM public.medicine_batches
    WHERE id = (it->>'batch_id')::uuid AND branch_id = v_branch;
    IF NOT FOUND THEN RAISE EXCEPTION 'Batch not found in this branch'; END IF;
    IF b.expiry <= v_today THEN RAISE EXCEPTION 'Batch % expired', b.batch_no; END IF;
    IF b.quarantined THEN RAISE EXCEPTION 'Batch % quarantined', b.batch_no; END IF;
    IF b.stock_status <> 'active' THEN RAISE EXCEPTION 'Batch % is %', b.batch_no, b.stock_status; END IF;

    v_avail := b.qty - public._billing_reserved_by_others(b.id, p_cart);
    IF v_avail < v_qty THEN
      RAISE EXCEPTION 'Insufficient stock: % (available %, requested %)', b.batch_no, greatest(v_avail, 0), v_qty;
    END IF;

    SELECT * INTO m FROM public.medicines
    WHERE id = b.medicine_id AND branch_id = v_branch AND active = true;
    IF NOT FOUND THEN RAISE EXCEPTION 'Medicine inactive or not found'; END IF;

    -- Defaults from batch → medicine master.
    v_def_mrp  := COALESCE(b.mrp, NULLIF(m.mrp, 0), m.selling_price);
    v_def_gst  := COALESCE(b.tax_rate, m.tax_rate, 0);
    v_incl     := COALESCE(b.price_includes_tax, m.price_includes_tax, true);
    v_def_disc := public.billing_default_discount_pct(m.mrp, m.selling_price, m.discount_percentage);
    v_manual   := COALESCE((it->>'manual')::boolean, false);

    v_mrp  := round(COALESCE((it->>'mrp')::numeric, v_def_mrp), 2);
    v_disc := round(COALESCE((it->>'discount_pct')::numeric, v_def_disc), 2);
    v_gst  := round(COALESCE((it->>'gst_pct')::numeric, v_def_gst), 2);

    -- MRP edits
    IF v_mrp < 0 THEN RAISE EXCEPTION 'MRP must not be negative'; END IF;
    IF v_mrp <> v_def_mrp THEN
      IF NOT public.billing_has_permission('sales.mrp_edit') THEN
        RAISE EXCEPTION 'You do not have permission to change MRP (%)', m.name;
      END IF;
      IF v_def_mrp > 0 AND v_mrp > v_def_mrp THEN
        RAISE EXCEPTION 'Selling price for % cannot exceed the printed MRP %', m.name, v_def_mrp;
      END IF;
    END IF;

    -- Discount edits
    IF v_disc < 0 OR v_disc > 100 THEN RAISE EXCEPTION 'Discount percentage must be between 0 and 100'; END IF;
    IF v_disc <> v_def_disc THEN
      IF NOT public.billing_has_permission('sales.discount') THEN
        RAISE EXCEPTION 'You do not have permission to change discounts (%)', m.name;
      END IF;
      IF v_disc > greatest(v_max_disc, v_def_disc) THEN
        RAISE EXCEPTION 'Discount % %% on % exceeds the permitted maximum %', v_disc, m.name, v_max_disc;
      END IF;
    END IF;

    -- GST edits
    IF NOT EXISTS (SELECT 1 FROM public.gst_rate_slabs WHERE rate = v_gst AND active) THEN
      RAISE EXCEPTION 'GST rate % %% is not a configured GST rate', v_gst;
    END IF;
    IF v_gst <> v_def_gst AND NOT public.billing_has_permission('sales.gst_edit') THEN
      RAISE EXCEPTION 'You do not have permission to change GST (%)', m.name;
    END IF;

    SELECT * INTO v_calc FROM public.billing_calc_line(v_mrp, v_qty, v_disc, v_gst, v_incl);

    UPDATE public.medicine_batches SET qty = qty - v_qty WHERE id = b.id;

    INSERT INTO public.sales_items (
      branch_id, invoice_id, medicine_id, batch_id, qty, unit_price, tax_rate, line_total,
      mrp, discount_pct, discount_amount, taxable_amount, gst_amount, price_includes_tax, manual_batch
    ) VALUES (
      v_branch, inv, m.id, b.id, v_qty, v_mrp, v_gst, v_calc.total_amount,
      v_mrp, v_disc, v_calc.discount_amount, v_calc.taxable_amount, v_calc.gst_amount, v_incl, v_manual
    );

    sub := sub + v_calc.total_amount;
    tx := tx + v_calc.gst_amount;
    v_line_disc := v_line_disc + v_calc.discount_amount;
    v_taxable := v_taxable + v_calc.taxable_amount;

    IF v_mrp <> v_def_mrp OR v_disc <> v_def_disc OR v_gst <> v_def_gst OR v_manual THEN
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'medicine', m.name, 'batch_no', b.batch_no, 'qty', v_qty,
        'before', jsonb_build_object('mrp', v_def_mrp, 'discount_pct', v_def_disc, 'gst_pct', v_def_gst),
        'after',  jsonb_build_object('mrp', v_mrp, 'discount_pct', v_disc, 'gst_pct', v_gst),
        'manual_batch', v_manual, 'override_reason', left(it->>'override_reason', 300)));
    END IF;
  END LOOP;

  tot := round(sub - v_discount, 2);
  IF tot < 0 THEN RAISE EXCEPTION 'Discount exceeds total'; END IF;
  IF p_expected_total IS NOT NULL AND abs(tot - round(p_expected_total, 2)) > 0.005 THEN
    RAISE EXCEPTION 'Bill total changed (server %, screen %). Review the bill and try again.', tot, round(p_expected_total, 2);
  END IF;

  FOR pm IN SELECT value FROM jsonb_array_elements(p_payments) LOOP
    IF COALESCE(pm->>'method', '') NOT IN ('cash','upi','card') THEN RAISE EXCEPTION 'Invalid payment method'; END IF;
    IF pm->>'amount' IS NULL THEN RAISE EXCEPTION 'Missing payment amount'; END IF;
    v_amount := round((pm->>'amount')::numeric, 2);
    IF v_amount <= 0 THEN RAISE EXCEPTION 'Invalid payment amount'; END IF;
    paid := round(paid + v_amount, 2);
    IF paid > tot THEN RAISE EXCEPTION 'Payments (%) exceed invoice total (%)', paid, tot; END IF;
    INSERT INTO public.payments (branch_id, invoice_id, method, amount)
    VALUES (v_branch, inv, pm->>'method', v_amount);
  END LOOP;

  v_credit_due := round(tot - paid, 2);
  IF v_credit_due > 0 THEN
    IF p_customer IS NULL THEN RAISE EXCEPTION 'An active customer is required for an unpaid balance'; END IF;
    v_outstanding := public.customer_outstanding(p_customer);
    IF round(v_outstanding + v_credit_due, 2) > v_customer.credit_limit THEN
      RAISE EXCEPTION 'Customer credit limit exceeded. Available: %',
        greatest(0, round(v_customer.credit_limit - v_outstanding, 2));
    END IF;
    INSERT INTO public.payments (branch_id, invoice_id, method, amount)
    VALUES (v_branch, inv, 'credit', v_credit_due);
  END IF;
  IF round(paid + v_credit_due, 2) <> tot THEN
    RAISE EXCEPTION 'Payment allocation does not equal invoice total';
  END IF;

  UPDATE public.sales_invoices
  SET subtotal = sub, tax = tx, total = tot, line_discount = v_line_disc, taxable_total = v_taxable
  WHERE id = inv;

  -- Stock is now permanently deducted; release this bill's reservations.
  IF p_cart IS NOT NULL THEN
    DELETE FROM public.stock_reservations WHERE cart_token = p_cart;
  END IF;

  INSERT INTO public.audit_logs (branch_id, user_id, action, entity_type, entity_id, reason, before_data, after_data)
  VALUES (v_branch, auth.uid(), 'sale_finalized', 'sales_invoice', inv::text, 'POS sale completed (FEFO v2)', NULL,
          jsonb_build_object('invoice_id', inv, 'invoice_total', tot, 'subtotal', sub, 'tax', tx,
                             'line_discount', v_line_disc, 'taxable_total', v_taxable, 'discount', v_discount,
                             'cart_token', p_cart, 'line_overrides', jsonb_array_length(v_changes)));

  IF jsonb_array_length(v_changes) > 0 THEN
    INSERT INTO public.audit_logs (branch_id, user_id, action, entity_type, entity_id, reason, before_data, after_data)
    VALUES (v_branch, auth.uid(), 'billing_line_overrides', 'sales_invoice', inv::text,
            'Discount / GST / MRP / batch changes on finalized bill', NULL, v_changes);
  END IF;

  RETURN inv;
END;
$function$

returns void | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public.finance_post_purchase_journal(p_invoice uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid := public.my_branch_id();
  v_inv public.purchase_invoices%rowtype;
begin
  select *
  into v_inv
  from public.purchase_invoices
  where id = p_invoice
    and branch_id = v_branch;

  if not found or v_inv.total <= 0
     or v_inv.status <> 'confirmed' then
    return;
  end if;

  if exists (
    select 1
    from public.financial_ledger
    where branch_id = v_branch
      and ref_type = 'purchase_invoice'
      and ref_id = p_invoice
  ) then
    return;
  end if;

  perform public.post_journal(
    'purchase_invoice',
    p_invoice,
    'Purchase ' || v_inv.supplier_invoice_no,
    jsonb_build_array(
      jsonb_build_object(
        'account', 'purchases',
        'debit', v_inv.total,
        'credit', 0
      ),
      jsonb_build_object(
        'account', 'payables',
        'debit', 0,
        'credit', v_inv.total,
        'party_type', 'distributor',
        'party_id', v_inv.distributor_id
      )
    )
  );
end;
$function$

returns void | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public.finance_post_sale_journal(p_invoice uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid := public.my_branch_id();
  v_inv public.sales_invoices%rowtype;
  v_lines jsonb;
begin
  select *
  into v_inv
  from public.sales_invoices
  where id = p_invoice
    and branch_id = v_branch;

  if not found or v_inv.total <= 0 or v_inv.status <> 'final' then
    return;
  end if;

  if exists (
    select 1
    from public.financial_ledger
    where branch_id = v_branch
      and ref_type = 'sales_invoice'
      and ref_id = p_invoice
  ) then
    return;
  end if;

  -- Wait until payment rows equal the invoice total.
  if (
    select round(coalesce(sum(p.amount),0),2)
    from public.payments p
    where p.invoice_id = p_invoice
      and p.branch_id = v_branch
  ) <> round(v_inv.total,2) then
    return;
  end if;

  select jsonb_agg(x)
  into v_lines
  from (
    select jsonb_build_object(
      'account',
        case when p.method = 'credit'
          then 'receivables'
          else p.method
        end,
      'debit', p.amount,
      'credit', 0,
      'party_type',
        case when p.method = 'credit'
          then 'customer'
          else null
        end,
      'party_id',
        case when p.method = 'credit'
          then v_inv.customer_id
          else null
        end
    ) as x
    from public.payments p
    where p.invoice_id = p_invoice
      and p.branch_id = v_branch

    union all

    select jsonb_build_object(
      'account', 'sales',
      'debit', 0,
      'credit', v_inv.total
    )
  ) q;

  if v_lines is not null then
    perform public.post_journal(
      'sales_invoice',
      p_invoice,
      'Sale ' || v_inv.invoice_no,
      v_lines
    );
  end if;
end;
$function$

