returns jsonb | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.opening_stock_get_draft()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_branch uuid := public.my_branch_id(); v_session public.opening_stock_sessions%rowtype; v_items jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL THEN RAISE EXCEPTION 'Login and active branch required'; END IF;
  IF coalesce(public.my_role(),'') NOT IN ('super_admin','admin') THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF NOT coalesce(app.session_ok(),false) THEN RAISE EXCEPTION 'An active work session is required'; END IF;
  SELECT * INTO v_session FROM public.opening_stock_sessions WHERE branch_id=v_branch;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id',i.id,'medicine_id',i.medicine_id,'medicine_name',m.name,'strength',m.strength,
    'batch_no',i.batch_no,'expiry',i.expiry,'qty',i.qty,'unit_cost',i.unit_cost,
    'mrp',i.mrp,'selling_price',i.selling_price
  ) ORDER BY m.name,i.batch_no),'[]'::jsonb)
  INTO v_items FROM public.opening_stock_items i
  JOIN public.medicines m ON m.id=i.medicine_id
  WHERE i.session_id=v_session.id AND i.branch_id=v_branch;
  RETURN jsonb_build_object('id',v_session.id,'status',v_session.status,'notes',v_session.notes,
    'created_at',v_session.created_at,'updated_at',v_session.updated_at,
    'submitted_at',v_session.submitted_at,'items',v_items);
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.opening_stock_save_draft(p_items jsonb, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_branch uuid := public.my_branch_id(); v_session public.opening_stock_sessions%rowtype; x jsonb; v_med uuid;
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL THEN RAISE EXCEPTION 'Login and active branch required'; END IF;
  IF coalesce(public.my_role(),'') NOT IN ('super_admin','admin') THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF NOT coalesce(app.session_ok(),false) THEN RAISE EXCEPTION 'An active work session is required'; END IF;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Add at least one stock batch'; END IF;
  IF jsonb_array_length(p_items) > 2000 THEN RAISE EXCEPTION 'Maximum 2,000 batch rows per draft'; END IF;
  INSERT INTO public.opening_stock_sessions(branch_id,status,notes,created_by,updated_by)
  VALUES(v_branch,'draft',nullif(trim(p_notes),''),auth.uid(),auth.uid())
  ON CONFLICT(branch_id) DO NOTHING;
  SELECT * INTO v_session FROM public.opening_stock_sessions WHERE branch_id=v_branch FOR UPDATE;
  IF v_session.status <> 'draft' THEN RAISE EXCEPTION 'Opening stock has already been submitted and is locked'; END IF;
  DELETE FROM public.opening_stock_items WHERE session_id=v_session.id;
  FOR x IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_med := (x->>'medicine_id')::uuid;
    IF NOT EXISTS (SELECT 1 FROM public.medicines m WHERE m.id=v_med AND m.branch_id=v_branch AND m.active) THEN
      RAISE EXCEPTION 'Medicine missing, inactive or outside this branch';
    END IF;
    IF coalesce(trim(x->>'batch_no'),'')='' OR nullif(x->>'expiry','') IS NULL
      OR coalesce((x->>'qty')::numeric,0)<=0
      OR coalesce((x->>'unit_cost')::numeric,-1)<0
      OR coalesce((x->>'mrp')::numeric,-1)<0
      OR coalesce((x->>'selling_price')::numeric,-1)<0 THEN
      RAISE EXCEPTION 'Invalid batch, expiry, quantity or price details';
    END IF;
    INSERT INTO public.opening_stock_items(session_id,branch_id,medicine_id,batch_no,expiry,qty,unit_cost,mrp,selling_price)
    VALUES(v_session.id,v_branch,v_med,trim(x->>'batch_no'),(x->>'expiry')::date,
      (x->>'qty')::numeric,(x->>'unit_cost')::numeric,(x->>'mrp')::numeric,(x->>'selling_price')::numeric);
  END LOOP;
  UPDATE public.opening_stock_sessions SET notes=nullif(trim(p_notes),''),updated_by=auth.uid(),updated_at=now()
  WHERE id=v_session.id;
  RETURN v_session.id;
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.opening_stock_submit()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_branch uuid := public.my_branch_id(); v_session public.opening_stock_sessions%rowtype; i public.opening_stock_items%rowtype; v_batch uuid; v_count integer:=0; v_value numeric:=0;
BEGIN
  IF auth.uid() IS NULL OR v_branch IS NULL THEN RAISE EXCEPTION 'Login and active branch required'; END IF;
  IF coalesce(public.my_role(),'') NOT IN ('super_admin','admin') THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF NOT coalesce(app.session_ok(),false) THEN RAISE EXCEPTION 'An active work session is required'; END IF;
  SELECT * INTO v_session FROM public.opening_stock_sessions WHERE branch_id=v_branch FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No saved opening-stock draft'; END IF;
  IF v_session.status <> 'draft' THEN RAISE EXCEPTION 'Opening stock has already been submitted'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.opening_stock_items WHERE session_id=v_session.id) THEN RAISE EXCEPTION 'Draft is empty'; END IF;
  IF EXISTS (SELECT 1 FROM public.opening_stock_items WHERE session_id=v_session.id GROUP BY medicine_id HAVING count(DISTINCT (mrp,selling_price)) > 1) THEN
    RAISE EXCEPTION 'A medicine has different MRP or selling prices across its batches. The medicine master supports one price per medicine; make the prices consistent before submitting.';
  END IF;
  FOR i IN SELECT * FROM public.opening_stock_items WHERE session_id=v_session.id AND branch_id=v_branch ORDER BY id LOOP
    IF EXISTS (SELECT 1 FROM public.medicine_batches b WHERE b.medicine_id=i.medicine_id AND b.batch_no=i.batch_no) THEN
      RAISE EXCEPTION 'Batch % already exists for this medicine. Resolve the duplicate before submitting.',i.batch_no;
    END IF;
    INSERT INTO public.medicine_batches(branch_id,medicine_id,batch_no,expiry,qty,quarantined,unit_cost)
    VALUES(v_branch,i.medicine_id,i.batch_no,i.expiry,i.qty,(i.expiry<=current_date),i.unit_cost)
    RETURNING id INTO v_batch;
    INSERT INTO public.stock_movements(branch_id,medicine_id,batch_id,movement_type,qty,ref_type,ref_id,created_by,reason)
    VALUES(v_branch,i.medicine_id,v_batch,'opening_stock',i.qty,'opening_stock',v_session.id,auth.uid(),
      CASE WHEN i.expiry<=current_date THEN 'Takeover opening stock; expired batch quarantined' ELSE 'Pharmacy takeover opening stock' END);
    UPDATE public.medicines SET mrp=i.mrp,selling_price=i.selling_price WHERE id=i.medicine_id AND branch_id=v_branch;
    v_count:=v_count+1; v_value:=v_value+(i.qty*i.unit_cost);
  END LOOP;
  UPDATE public.opening_stock_sessions SET status='submitted',submitted_by=auth.uid(),submitted_at=now(),updated_at=now(),updated_by=auth.uid()
  WHERE id=v_session.id;
  INSERT INTO public.audit_logs(branch_id,user_id,action,entity_type,entity_id,reason,before_data,after_data,at)
  VALUES(v_branch,auth.uid(),'opening_stock_submitted','opening_stock_session',v_session.id::text,
    'Initial takeover stock posted',jsonb_build_object('status','draft'),
    jsonb_build_object('status','submitted','batch_count',v_count,'stock_value',round(v_value,2)),now());
  RETURN v_session.id;
END;
$function$

returns integer | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.physical_count(p_counts jsonb, p_note text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid;
  v_item jsonb;
  v_batch public.medicine_batches%rowtype;
  v_counted numeric;
  v_delta numeric;
  v_adjusted integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  v_branch := public.my_branch_id();
  if v_branch is null then
    raise exception 'No active branch assigned';
  end if;

  if coalesce(public.my_role(), '') not in
    ('super_admin', 'admin', 'pharmacist', 'inventory') then
    raise exception 'Not authorised';
  end if;

  if jsonb_typeof(p_counts) <> 'array' then
    raise exception 'Counts must be a JSON array';
  end if;
  if coalesce(trim(p_note), '') = '' then
    raise exception 'A note is required';
  end if;

  for v_item in
    select value from jsonb_array_elements(p_counts)
  loop
    if not (v_item ? 'batch_id') or not (v_item ? 'counted') then
      raise exception 'Each count needs batch_id and counted';
    end if;

    v_counted := (v_item ->> 'counted')::numeric;
    if v_counted < 0 then
      raise exception 'Counted quantity cannot be negative';
    end if;

    select *
      into v_batch
    from public.medicine_batches
    where id = (v_item ->> 'batch_id')::uuid
      and branch_id = v_branch
    for update;

    if not found then
      raise exception 'Batch not found in this branch';
    end if;

    v_delta := v_counted - v_batch.qty;
    if v_delta <> 0 then
      update public.medicine_batches
      set qty = v_counted
      where id = v_batch.id
        and branch_id = v_branch;

      insert into public.stock_movements
        (branch_id, medicine_id, batch_id, movement_type, qty,
         ref_type, reason, created_by)
      values
        (v_branch, v_batch.medicine_id, v_batch.id, 'physical_count',
         v_delta, 'physical_count', trim(p_note), auth.uid());

      v_adjusted := v_adjusted + 1;
    end if;
  end loop;

  insert into public.audit_logs
    (branch_id, user_id, action, entity_type, entity_id,
     reason, before_data, after_data, at)
  values
    (v_branch, auth.uid(), 'physical_count', 'inventory',
     null, trim(p_note), null,
     jsonb_build_object('adjusted_batches', v_adjusted), now());

  return v_adjusted;
end;
$function$

returns uuid | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public.post_journal(p_ref_type text, p_ref_id uuid, p_memo text, p_lines jsonb, p_reversal_of uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_journal uuid := gen_random_uuid();
    v_line jsonb;
    v_debit numeric := 0;
    v_credit numeric := 0;
    v_account text;
    v_d numeric;
    v_c numeric;
    v_party_type text;
    v_party_id uuid;
BEGIN
    IF auth.uid() IS NULL OR v_branch IS NULL THEN
        RAISE EXCEPTION 'Login and active branch required';
    END IF;

    IF COALESCE(public.my_role(), '') NOT IN (
        'super_admin',
        'admin',
        'pharmacist',
        'billing',
        'billing_staff',
        'inventory'
    ) THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF jsonb_typeof(p_lines) <> 'array'
       OR jsonb_array_length(p_lines) < 2 THEN
        RAISE EXCEPTION 'Journal requires at least two lines';
    END IF;

    FOR v_line IN
        SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        v_account := v_line->>'account';
        v_d := COALESCE(
            NULLIF(v_line->>'debit', '')::numeric,
            0
        );
        v_c := COALESCE(
            NULLIF(v_line->>'credit', '')::numeric,
            0
        );

        IF v_account NOT IN (
            'cash',
            'upi',
            'card',
            'bank',
            'receivables',
            'payables',
            'sales',
            'sales_returns',
            'purchases',
            'purchase_returns',
            'expenses',
            'opening_balance_equity'
        )
        OR v_d < 0
        OR v_c < 0
        OR NOT (
            (v_d > 0 AND v_c = 0)
            OR
            (v_c > 0 AND v_d = 0)
        ) THEN
            RAISE EXCEPTION 'Invalid journal line';
        END IF;

        IF (
            NULLIF(v_line->>'party_type', '') IS NOT NULL
            AND NULLIF(v_line->>'party_type', '')
                NOT IN ('customer', 'distributor')
        ) THEN
            RAISE EXCEPTION 'Invalid party type';
        END IF;

        v_debit := v_debit + v_d;
        v_credit := v_credit + v_c;
    END LOOP;

    IF v_debit <= 0
       OR round(v_debit, 2) <> round(v_credit, 2) THEN
        RAISE EXCEPTION
            'Unbalanced journal (debit %, credit %)',
            v_debit,
            v_credit;
    END IF;

    FOR v_line IN
        SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        v_party_type := NULLIF(
            v_line->>'party_type',
            ''
        );

        v_party_id := NULLIF(
            v_line->>'party_id',
            ''
        )::uuid;

        INSERT INTO public.financial_ledger (
            branch_id,
            journal_id,
            account,
            debit,
            credit,
            party_type,
            party_id,
            ref_type,
            ref_id,
            memo,
            reversal_of,
            created_by
        )
        VALUES (
            v_branch,
            v_journal,
            v_line->>'account',
            COALESCE(
                NULLIF(v_line->>'debit', '')::numeric,
                0
            ),
            COALESCE(
                NULLIF(v_line->>'credit', '')::numeric,
                0
            ),
            v_party_type,
            v_party_id,
            p_ref_type,
            p_ref_id,
            p_memo,
            p_reversal_of,
            auth.uid()
        );
    END LOOP;

    RETURN v_journal;
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.process_sales_return(p_invoice uuid, p_items jsonb, p_method text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_role text := COALESCE(public.my_role(), '');
    inv public.sales_invoices%ROWTYPE;
    si public.sales_items%ROWTYPE;
    it jsonb;
    rq numeric;
    done numeric;
    factor numeric;
    line_amount numeric;
    line_tax numeric;
    subtotal_return numeric := 0;
    tax_return numeric := 0;
    disposition text;
    return_id uuid;
    return_item_id uuid;
    return_number text;

    v_return_base numeric;
    v_to_restore numeric;
    v_available numeric;
    v_take numeric;
    v_alloc record;
    v_updated integer;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF NOT COALESCE(app.session_ok(), false) THEN
        RAISE EXCEPTION 'An active work session is required';
    END IF;

    IF v_role NOT IN (
        'super_admin', 'admin', 'pharmacist', 'billing_staff'
    ) THEN
        RAISE EXCEPTION 'Not authorised';
    END IF;

    IF v_branch IS NULL THEN
        RAISE EXCEPTION 'No branch assigned';
    END IF;

    IF COALESCE(TRIM(p_reason), '') = '' THEN
        RAISE EXCEPTION 'A reason is required';
    END IF;

    IF p_method NOT IN ('cash', 'upi') THEN
        RAISE EXCEPTION 'Refund method must be Cash or UPI';
    END IF;

    IF jsonb_typeof(p_items) <> 'array'
       OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Nothing selected to return';
    END IF;

    SELECT *
    INTO inv
    FROM public.sales_invoices
    WHERE id = p_invoice
      AND branch_id = v_branch
      AND status = 'final'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invoice not found';
    END IF;

    factor := CASE
        WHEN inv.subtotal > 0 THEN inv.total / inv.subtotal
        ELSE 1
    END;

    return_number :=
        'CN-' ||
        to_char(now() AT TIME ZONE 'Asia/Kolkata', 'YYMM') ||
        '-' ||
        lpad(nextval('public.sales_return_doc_seq')::text, 6, '0');

    INSERT INTO public.sales_returns (
        branch_id, return_no, invoice_id, customer_id,
        reason, refund_method, created_by
    )
    VALUES (
        v_branch, return_number, p_invoice, inv.customer_id,
        TRIM(p_reason), p_method, auth.uid()
    )
    RETURNING id INTO return_id;

    FOR it IN
        SELECT value FROM jsonb_array_elements(p_items)
    LOOP
        IF COALESCE(it->>'sales_item_id', '') = '' THEN
            RAISE EXCEPTION 'Invalid sale item';
        END IF;

        SELECT *
        INTO si
        FROM public.sales_items
        WHERE id = (it->>'sales_item_id')::uuid
          AND invoice_id = p_invoice
          AND branch_id = v_branch
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Item does not belong to this invoice';
        END IF;

        rq := (it->>'qty')::numeric;

        IF rq IS NULL OR rq <= 0 THEN
            RAISE EXCEPTION 'Invalid return quantity';
        END IF;

        SELECT COALESCE(SUM(sri.qty), 0)
        INTO done
        FROM public.sales_return_items sri
        JOIN public.sales_returns sr ON sr.id = sri.return_id
        WHERE sri.sales_item_id = si.id
          AND sr.branch_id = v_branch;

        IF done + rq > si.qty THEN
            RAISE EXCEPTION
                'Cannot return more than sold. Sold %, already returned %',
                si.qty, done;
        END IF;

        disposition := COALESCE(it->>'disposition', 'restock');

        IF disposition NOT IN ('restock', 'damaged') THEN
            RAISE EXCEPTION 'Invalid item condition';
        END IF;

        line_amount := ROUND(si.unit_price * rq * factor, 2);

        line_tax := CASE
            WHEN (100 + si.tax_rate) > 0
            THEN ROUND(
                line_amount * si.tax_rate / (100 + si.tax_rate), 2
            )
            ELSE 0
        END;

        IF line_amount <= 0 THEN
            RAISE EXCEPTION 'Return amount must be positive';
        END IF;

        -- Convert the returned sale quantity into base units.
        v_return_base := rq * COALESCE(
            si.base_qty / NULLIF(si.qty, 0),
            si.unit_factor,
            1
        );

        INSERT INTO public.sales_return_items (
            branch_id, return_id, sales_item_id,
            medicine_id, batch_id, qty, base_qty,
            disposition, line_total
        )
        VALUES (
            v_branch, return_id, si.id,
            si.medicine_id, si.batch_id, rq, v_return_base,
            disposition, line_amount
        )
        RETURNING id INTO return_item_id;

        IF disposition = 'restock' THEN

            -- Restore physical stock to the original batch.
            UPDATE public.medicine_batches
            SET qty = qty + v_return_base
            WHERE id = si.batch_id
              AND medicine_id = si.medicine_id
              AND branch_id = v_branch;

            IF NOT FOUND THEN
                RAISE EXCEPTION
                    'Original batch not found in this branch';
            END IF;

            -- Restore the original FIFO sale allocations.
            v_to_restore := v_return_base;

            FOR v_alloc IN
                SELECT
                    sa.id AS sale_allocation_id,
                    sa.cost_layer_id,
                    sa.qty,
                    sa.unit_cost,
                    COALESCE((
                        SELECT SUM(cra.qty)
                        FROM public.inventory_customer_return_allocations cra
                        WHERE cra.sale_allocation_id = sa.id
                    ), 0) AS already_restored
                FROM public.inventory_sale_allocations sa
                WHERE sa.sales_item_id = si.id
                  AND sa.branch_id = v_branch
                ORDER BY sa.created_at, sa.id
                FOR UPDATE
            LOOP
                EXIT WHEN v_to_restore <= 0;

                v_available := v_alloc.qty - v_alloc.already_restored;

                IF v_available <= 0 THEN
                    CONTINUE;
                END IF;

                v_take := LEAST(v_to_restore, v_available);

                UPDATE public.inventory_cost_layers
                SET remaining_qty = remaining_qty + v_take
                WHERE id = v_alloc.cost_layer_id
                  AND branch_id = v_branch
                  AND batch_id = si.batch_id;

                GET DIAGNOSTICS v_updated = ROW_COUNT;

                IF v_updated <> 1 THEN
                    RAISE EXCEPTION
                        'Original FIFO cost layer could not be restored';
                END IF;

                INSERT INTO public.inventory_customer_return_allocations (
                    branch_id,
                    sales_return_item_id,
                    sale_allocation_id,
                    qty,
                    unit_cost,
                    restored_cost
                )
                VALUES (
                    v_branch,
                    return_item_id,
                    v_alloc.sale_allocation_id,
                    v_take,
                    v_alloc.unit_cost,
                    CASE
                        WHEN v_alloc.unit_cost IS NULL THEN NULL
                        ELSE ROUND(v_take * v_alloc.unit_cost, 6)
                    END
                );

                v_to_restore := v_to_restore - v_take;
            END LOOP;

            IF v_to_restore > 0 THEN
                RAISE EXCEPTION
                    'Original FIFO allocation insufficient for return. Unallocated base quantity: %',
                    v_to_restore;
            END IF;

            INSERT INTO public.stock_movements (
                branch_id, medicine_id, batch_id,
                movement_type, qty, ref_type, ref_id,
                created_by, reason
            )
            VALUES (
                v_branch, si.medicine_id, si.batch_id,
                'return_in', v_return_base,
                'sales_return', return_id,
                auth.uid(), 'Customer return ' || return_number
            );
        END IF;

        subtotal_return := subtotal_return + line_amount;
        tax_return := tax_return + line_tax;
    END LOOP;

    IF subtotal_return <= 0 THEN
        RAISE EXCEPTION 'Return amount is zero';
    END IF;

    UPDATE public.sales_returns
    SET total = subtotal_return,
        tax = tax_return
    WHERE id = return_id
      AND branch_id = v_branch;

    INSERT INTO public.audit_logs (
        branch_id, user_id, action, entity_type,
        entity_id, reason, before_data, after_data
    )
    VALUES (
        v_branch, auth.uid(), 'sales_return_created',
        'sales_return', return_id::text,
        TRIM(p_reason), NULL,
        jsonb_build_object(
            'return_no', return_number,
            'invoice_id', p_invoice,
            'total', subtotal_return,
            'tax', tax_return,
            'refund_method', p_method
        )
    );

    RETURN return_id;
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.record_daily_cash_opening(p_opening_date date, p_amount numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_branch uuid := public.my_branch_id();
  v_id uuid := gen_random_uuid();
  v_journal uuid;
BEGIN
  -- Any authenticated staff/admin profile assigned to this active branch may
  -- submit the branch-wide opening. UNIQUE(branch_id, opening_date) ensures
  -- that only the first submission can be recorded for that day.
  IF auth.uid() IS NULL OR v_branch IS NULL OR public.my_role() IS NULL THEN
    RAISE EXCEPTION 'Login with an active branch staff profile is required';
  END IF;

  IF p_opening_date IS NULL OR p_opening_date > (now() AT TIME ZONE 'Asia/Kolkata')::date THEN
    RAISE EXCEPTION 'Invalid opening date';
  END IF;

  IF p_amount IS NULL OR p_amount < 0 OR p_amount > 999999999999.99 THEN
    RAISE EXCEPTION 'Enter a valid non-negative opening amount';
  END IF;

  INSERT INTO public.daily_cash_openings (
    id, branch_id, opening_date, amount, created_by
  ) VALUES (
    v_id, v_branch, p_opening_date, round(p_amount,2), auth.uid()
  );

  IF round(p_amount,2) > 0 THEN
    v_journal := public.post_journal(
      'daily_cash_opening',
      v_id,
      'Daily cash opening - ' || to_char(p_opening_date, 'DD Mon YYYY'),
      jsonb_build_array(
        jsonb_build_object('account','cash','debit',round(p_amount,2),'credit',0),
        jsonb_build_object('account','opening_balance_equity','debit',0,'credit',round(p_amount,2))
      ),
      NULL
    );

    UPDATE public.daily_cash_openings
    SET journal_id = v_journal
    WHERE id = v_id;
  END IF;

  RETURN v_id;
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'Daily cash opening is already recorded for this branch and date. It cannot be submitted twice.';
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.record_party_opening_balance(p_party_type text, p_party_id uuid, p_amount numeric, p_balance_side text, p_as_of_date date DEFAULT CURRENT_DATE, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid := public.my_branch_id();
    v_id uuid := gen_random_uuid();
    v_journal uuid := gen_random_uuid();
    v_party_name text;
    v_debit_account text;
    v_credit_account text;
    v_debit_party_type text;
    v_debit_party_id uuid;
    v_credit_party_type text;
    v_credit_party_id uuid;
    v_entry_at timestamptz;
BEGIN
    IF auth.uid() IS NULL OR v_branch IS NULL THEN
        RAISE EXCEPTION 'Login and active branch required';
    END IF;

    IF COALESCE(public.my_role(), '') NOT IN (
        'super_admin',
        'admin'
    ) THEN
        RAISE EXCEPTION 'Only Admin can record opening balances';
    END IF;

    IF p_party_type NOT IN ('customer', 'distributor') THEN
        RAISE EXCEPTION 'Invalid party type';
    END IF;

    IF p_balance_side NOT IN ('debit', 'credit') THEN
        RAISE EXCEPTION 'Choose Debit or Credit';
    END IF;

    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'Opening balance must be greater than zero';
    END IF;

    IF p_as_of_date IS NULL OR p_as_of_date > CURRENT_DATE THEN
        RAISE EXCEPTION 'Invalid opening balance date';
    END IF;

    -- Lock and verify the party in the active branch.
    IF p_party_type = 'customer' THEN

        SELECT name
        INTO v_party_name
        FROM public.customers
        WHERE id = p_party_id
          AND branch_id = v_branch
          AND active = true
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Customer not found or inactive in this branch';
        END IF;

        -- Customer debit: customer owes the pharmacy.
        -- Customer credit: customer has an advance.
        v_debit_account := 'receivables';
        v_credit_account := 'opening_balance_equity';

        IF p_balance_side = 'debit' THEN
            v_debit_party_type := 'customer';
            v_debit_party_id := p_party_id;
        ELSE
            v_debit_account := 'opening_balance_equity';
            v_credit_account := 'receivables';
            v_credit_party_type := 'customer';
            v_credit_party_id := p_party_id;
        END IF;

    ELSE

        SELECT name
        INTO v_party_name
        FROM public.distributors
        WHERE id = p_party_id
          AND branch_id = v_branch
          AND active = true
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Distributor not found or inactive in this branch';
        END IF;

        -- Distributor credit: pharmacy owes supplier.
        -- Distributor debit: pharmacy has an advance.
        v_debit_account := 'payables';
        v_credit_account := 'opening_balance_equity';

        IF p_balance_side = 'credit' THEN
            v_debit_account := 'opening_balance_equity';
            v_credit_account := 'payables';
            v_credit_party_type := 'distributor';
            v_credit_party_id := p_party_id;
        ELSE
            v_debit_party_type := 'distributor';
            v_debit_party_id := p_party_id;
        END IF;

    END IF;

    -- The partial unique index prevents a second active entry.
    INSERT INTO public.party_opening_balances (
        id,
        branch_id,
        party_type,
        customer_id,
        distributor_id,
        amount,
        balance_side,
        as_of_date,
        note,
        status,
        journal_id,
        created_by
    )
    VALUES (
        v_id,
        v_branch,
        p_party_type,
        CASE WHEN p_party_type = 'customer'
            THEN p_party_id ELSE NULL END,
        CASE WHEN p_party_type = 'distributor'
            THEN p_party_id ELSE NULL END,
        p_amount,
        p_balance_side,
        p_as_of_date,
        NULLIF(TRIM(p_note), ''),
        'posted',
        v_journal,
        auth.uid()
    );

    v_entry_at :=
        p_as_of_date::timestamp AT TIME ZONE 'Asia/Kolkata';

    -- Opening journal: exactly two balanced lines.
    INSERT INTO public.financial_ledger (
        branch_id,
        journal_id,
        entry_at,
        account,
        debit,
        credit,
        party_type,
        party_id,
        ref_type,
        ref_id,
        memo,
        created_by
    )
    VALUES
    (
        v_branch,
        v_journal,
        v_entry_at,
        v_debit_account,
        p_amount,
        0,
        v_debit_party_type,
        v_debit_party_id,
        'opening_balance',
        v_id,
        'Opening balance - ' || v_party_name,
        auth.uid()
    ),
    (
        v_branch,
        v_journal,
        v_entry_at,
        v_credit_account,
        0,
        p_amount,
        v_credit_party_type,
        v_credit_party_id,
        'opening_balance',
        v_id,
        'Opening balance - ' || v_party_name,
        auth.uid()
    );

    RETURN v_id;
END;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.register_medicine_image(p_medicine uuid, p_path text, p_name text, p_mime text, p_size bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_branch uuid;
  v_count integer;
  v_id uuid;
  v_object record;
begin
  v_branch := public.my_branch_id();

  if auth.uid() is null or v_branch is null then
    raise exception 'Login and active branch required';
  end if;

  if public.my_role() not in
    ('super_admin','admin','pharmacist','inventory') then
    raise exception 'Not authorised';
  end if;

  if p_mime not in ('image/jpeg','image/png','image/webp')
     or p_size is null or p_size <= 0
     or p_size > 5242880 then
    raise exception 'Invalid image type or size';
  end if;

  if split_part(p_path,'/',1) <> p_medicine::text then
    raise exception 'Invalid medicine image path';
  end if;

  if not exists (
    select 1 from medicines
    where id = p_medicine and branch_id = v_branch
  ) then
    raise exception 'Medicine not found in active branch';
  end if;

  select * into v_object
  from storage.objects
  where bucket_id = 'medicine-images'
    and name = p_path;

  if not found then
    raise exception 'Uploaded image not found';
  end if;

  if (v_object.metadata->>'size') is not null
     and (v_object.metadata->>'size')::bigint <> p_size then
    raise exception 'Image size mismatch';
  end if;

  if (v_object.metadata->>'mimetype') is not null
     and v_object.metadata->>'mimetype' <> p_mime then
    raise exception 'Image type mismatch';
  end if;

  select count(*) into v_count
  from medicine_images
  where medicine_id = p_medicine
    and branch_id = v_branch;

  if v_count >= 8 then
    raise exception 'Maximum 8 photos per medicine';
  end if;

  insert into medicine_images (
    branch_id, medicine_id, path, file_name,
    mime, size_bytes, is_primary, sort_order, uploaded_by
  )
  values (
    v_branch, p_medicine, p_path, left(p_name,200),
    p_mime, p_size, v_count = 0, v_count, auth.uid()
  )
  returning id into v_id;

  insert into audit_logs (
    branch_id,user_id,action,entity_type,entity_id,
    after_data,at
  )
  values (
    v_branch,auth.uid(),'medicine_image_added',
    'medicine_image',v_id::text,
    jsonb_build_object('medicine_id',p_medicine,'file_name',p_name),
    now()
  );

  return v_id;
end;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.register_purchase_document(p_path text, p_name text, p_mime text, p_size bigint, p_sha256 text, p_distributor uuid DEFAULT NULL::uuid, p_purchase uuid DEFAULT NULL::uuid, p_doc_date date DEFAULT NULL::date, p_type text DEFAULT 'purchase_bill'::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage', 'pg_temp'
AS $function$
declare
  v_branch uuid;
  v_folder text;
  v_id uuid;
  v_object record;
begin
  v_branch := public.my_branch_id();

  if auth.uid() is null or v_branch is null then
    raise exception 'Login and active branch required';
  end if;

  if public.my_role() not in
    ('super_admin','admin','inventory') then
    raise exception 'Not authorised';
  end if;

  if p_mime not in (
    'application/pdf','image/jpeg','image/png','image/webp'
  ) or p_size is null or p_size <= 0
    or p_size > 15728640 then
    raise exception 'Invalid document type or size';
  end if;

  if p_type not in (
    'purchase_bill','credit_note','delivery_challan','other'
  ) then
    raise exception 'Invalid document type';
  end if;

  v_folder := split_part(p_path,'/',1);

  if v_folder <> coalesce(p_distributor::text,'unassigned') then
    raise exception 'Document path does not match distributor';
  end if;

  if p_distributor is not null and not exists (
    select 1 from distributors
    where id = p_distributor
      and branch_id = v_branch
  ) then
    raise exception 'Distributor not found in active branch';
  end if;

  if p_purchase is not null and not exists (
    select 1 from purchase_invoices
    where id = p_purchase
      and branch_id = v_branch
      and (p_distributor is null or distributor_id = p_distributor)
  ) then
    raise exception 'Purchase invoice not found in active branch';
  end if;

  select * into v_object
  from storage.objects
  where bucket_id = 'purchase-documents'
    and name = p_path;

  if not found then
    raise exception 'Uploaded document not found';
  end if;

  if (v_object.metadata->>'size') is not null
     and (v_object.metadata->>'size')::bigint <> p_size then
    raise exception 'Document size mismatch';
  end if;

  if p_sha256 is not null
     and p_sha256 !~* '^[0-9a-f]{64}$' then
    raise exception 'Invalid SHA256 hash';
  end if;

  insert into purchase_documents (
    branch_id,path,file_name,mime,size_bytes,sha256,
    distributor_id,purchase_invoice_id,doc_type,
    doc_date,notes,uploaded_by
  )
  values (
    v_branch,p_path,left(p_name,200),p_mime,p_size,
    lower(p_sha256),p_distributor,p_purchase,p_type,
    p_doc_date,nullif(trim(p_notes),''),
    auth.uid()
  )
  returning id into v_id;

  insert into audit_logs (
    branch_id,user_id,action,entity_type,entity_id,
    after_data,at
  )
  values (
    v_branch,auth.uid(),'purchase_document_added',
    'purchase_document',v_id::text,
    jsonb_build_object('file_name',p_name,'type',p_type),
    now()
  );

  return v_id;
end;
$function$

returns void | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.remove_purchase_document(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid;
  v_old record;
begin
  v_branch := public.my_branch_id();

  if auth.uid() is null or v_branch is null then
    raise exception 'Login and active branch required';
  end if;

  if public.my_role() not in ('super_admin','admin') then
    raise exception 'Not authorised';
  end if;

  if coalesce(trim(p_reason),'') = '' then
    raise exception 'Removal reason required';
  end if;

  update purchase_documents
  set status = 'removed',
      removed_reason = trim(p_reason),
      removed_at = now(),
      removed_by = auth.uid()
  where id = p_id
    and branch_id = v_branch
    and status = 'active'
  returning * into v_old;

  if not found then
    raise exception 'Document not found or already removed';
  end if;

  insert into audit_logs (
    branch_id,user_id,action,entity_type,entity_id,
    reason,before_data,at
  )
  values (
    v_branch,auth.uid(),'purchase_document_removed',
    'purchase_document',p_id::text,
    trim(p_reason),
    jsonb_build_object('file_name',v_old.file_name),
    now()
  );
end;
$function$

returns uuid | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.request_medicine_deactivation(p_medicine uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_branch uuid;
    v_request uuid;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    v_branch := public.my_branch_id();

    IF v_branch IS NULL OR public.my_role() IS NULL THEN
        RAISE EXCEPTION 'Active staff profile required';
    END IF;

    IF COALESCE(length(trim(p_reason)), 0) < 5 THEN
        RAISE EXCEPTION 'Please provide a reason of at least 5 characters';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.medicines
        WHERE id = p_medicine
          AND branch_id = v_branch
          AND active = true
    ) THEN
        RAISE EXCEPTION 'Active medicine not found in your branch';
    END IF;

    INSERT INTO public.medicine_deactivation_requests (
        branch_id,
        medicine_id,
        requested_by,
        reason
    )
    VALUES (
        v_branch,
        p_medicine,
        auth.uid(),
        trim(p_reason)
    )
    RETURNING id INTO v_request;

    RETURN v_request;
END;
$function$

returns TABLE(sales_item_id uuid, name text, strength text, batch_no text, qty_sold numeric, qty_returned numeric, unit_refund numeric) | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.returnable_items(p_invoice uuid)
 RETURNS TABLE(sales_item_id uuid, name text, strength text, batch_no text, qty_sold numeric, qty_returned numeric, unit_refund numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_branch uuid := public.my_branch_id();
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not coalesce(app.session_ok(), false) then raise exception 'An active work session is required'; end if;
  if coalesce(public.my_role(),'') not in ('super_admin','admin','pharmacist','billing_staff') then
    raise exception 'Not authorised';
  end if;
  if v_branch is null then raise exception 'No branch assigned'; end if;
  if not exists (
    select 1 from public.sales_invoices i
    where i.id = p_invoice and i.branch_id = v_branch and i.status = 'final'
  ) then raise exception 'Invoice not found'; end if;

  return query
  select si.id, m.name, m.strength, b.batch_no, si.qty,
         coalesce(r.returned_qty,0),
         case when i.subtotal > 0
              then round(si.unit_price * (i.total / i.subtotal), 2)
              else round(si.unit_price, 2) end
  from public.sales_items si
  join public.sales_invoices i on i.id = si.invoice_id and i.branch_id = v_branch
  join public.medicines m on m.id = si.medicine_id and m.branch_id = v_branch
  join public.medicine_batches b on b.id = si.batch_id and b.branch_id = v_branch
  left join (
    select sri.sales_item_id, sum(sri.qty) as returned_qty
    from public.sales_return_items sri
    join public.sales_returns sr on sr.id = sri.return_id and sr.branch_id = v_branch
    where sri.branch_id = v_branch
    group by sri.sales_item_id
  ) r on r.sales_item_id = si.id
  where si.invoice_id = p_invoice and si.branch_id = v_branch
  order by m.name, b.batch_no;
end;
$function$

returns uuid | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public.reverse_journal(p_journal uuid, p_memo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid := public.my_branch_id();
  v_ref_type text;
  v_ref_id uuid;
  v_lines jsonb;
begin
  if auth.uid() is null or v_branch is null then
    raise exception 'Login and active branch required';
  end if;

  if coalesce(public.my_role(),'') not in ('super_admin','admin') then
    raise exception 'Not authorised';
    end if;
      if exists (
    select 1
    from public.financial_ledger
    where branch_id = v_branch
      and reversal_of = p_journal
  ) then
    raise exception 'This journal has already been reversed';
  end if;

  select ref_type, ref_id
  into v_ref_type, v_ref_id
  from public.financial_ledger
  where branch_id = v_branch
    and journal_id = p_journal
  limit 1;

  if v_ref_type is null then
    raise exception 'Journal not found in this branch';
  end if;

  select jsonb_agg(
    jsonb_build_object(
      'account', account,
      'debit', credit,
      'credit', debit,
      'party_type', party_type,
      'party_id', party_id
    )
  )
  into v_lines
  from public.financial_ledger
  where branch_id = v_branch
    and journal_id = p_journal;

  return public.post_journal(
    v_ref_type, v_ref_id, p_memo, v_lines, p_journal
  );
end;
$function$

returns void | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.reverse_receipt(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_branch uuid := public.my_branch_id();
  v_receipt public.customer_receipts%rowtype;
begin
  if auth.uid() is null or v_branch is null then
    raise exception 'Login and active branch required';
  end if;

  if coalesce(public.my_role(),'') not in ('super_admin','admin') then
    raise exception 'Not authorised';
  end if;

  if coalesce(trim(p_reason),'') = '' then
    raise exception 'A reason is required';
  end if;

  select *
  into v_receipt
  from public.customer_receipts
  where id = p_id
    and branch_id = v_branch
  for update;

  if not found then
    raise exception 'Receipt not found in this branch';
  end if;

  if v_receipt.status <> 'posted'
     or v_receipt.journal_id is null then
    raise exception 'Receipt already reversed or journal missing';
  end if;

  perform public.reverse_journal(
    v_receipt.journal_id,
    'Reversal of ' || v_receipt.receipt_no || ': ' || trim(p_reason)
  );

  update public.customer_receipts
  set status = 'reversed',
      reversed_at = now(),
      reversal_reason = trim(p_reason)
  where id = p_id
    and branch_id = v_branch;

  insert into public.audit_logs(
    branch_id,user_id,action,entity_type,entity_id,
    reason,before_data,after_data,at
  )
  values (
    v_branch,auth.uid(),'customer_receipt_reversed',
    'customer_receipt',p_id::text,trim(p_reason),
    jsonb_build_object('status','posted'),
    jsonb_build_object('status','reversed'),
    now()
  );
end;
$function$

