returns boolean | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.review_medicine_deactivation(p_request uuid, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_request public.medicine_deactivation_requests%ROWTYPE;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF public.my_role() <> 'super_admin' THEN
        RAISE EXCEPTION 'Only Super Admin can review requests';
    END IF;

    SELECT *
    INTO v_request
    FROM public.medicine_deactivation_requests
    WHERE id = p_request
      AND branch_id = public.my_branch_id()
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Request not found in your branch';
    END IF;

    IF v_request.status <> 'pending' THEN
        RAISE EXCEPTION 'This request has already been reviewed';
    END IF;

    IF p_approve THEN
        UPDATE public.medicines
        SET active = false
        WHERE id = v_request.medicine_id
          AND branch_id = v_request.branch_id
          AND active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Medicine is not active or could not be found';
        END IF;
    END IF;

    UPDATE public.medicine_deactivation_requests
    SET
        status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
        reviewed_by = auth.uid(),
        reviewed_at = now(),
        review_note = NULLIF(trim(p_note), '')
    WHERE id = p_request;

    RETURN true;
END;
$function$

returns trigger | SECURITY DEFINER | grants: postgres,service_role
CREATE OR REPLACE FUNCTION public.sales_items_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_batch public.medicine_batches%ROWTYPE;
    v_layer public.inventory_cost_layers%ROWTYPE;
    v_needed numeric;
    v_take numeric;
BEGIN
    -- Existing authentication and branch validation
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF NEW.branch_id IS NULL
       OR NEW.branch_id <> public.my_branch_id() THEN
        RAISE EXCEPTION 'Sale item branch does not match current branch';
    END IF;

    SELECT *
    INTO v_batch
    FROM public.medicine_batches
    WHERE id = NEW.batch_id
      AND branch_id = NEW.branch_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Batch not found in this branch';
    END IF;

    IF v_batch.medicine_id <> NEW.medicine_id THEN
        RAISE EXCEPTION 'Medicine does not match batch';
    END IF;

    IF v_batch.expiry < CURRENT_DATE OR v_batch.quarantined THEN
        RAISE EXCEPTION 'Batch cannot be sold';
    END IF;

    -- Determine quantity in base units
    IF NEW.qty IS NULL OR NEW.qty <= 0 THEN
        RAISE EXCEPTION 'Invalid sale quantity';
    END IF;

    IF NEW.unit_factor IS NOT NULL AND NEW.unit_factor <= 0 THEN
        RAISE EXCEPTION 'Invalid sale unit factor';
    END IF;

    v_needed := COALESCE(
        NEW.base_qty,
        NEW.qty * COALESCE(NEW.unit_factor, 1)
    );

    IF v_needed <= 0 THEN
        RAISE EXCEPTION 'Invalid sale base quantity';
    END IF;

    -- Existing stock movement
    INSERT INTO public.stock_movements
        (branch_id, medicine_id, batch_id, movement_type, qty,
         ref_type, ref_id, created_by, reason)
    VALUES
        (NEW.branch_id, NEW.medicine_id, NEW.batch_id, 'sale_out',
         -NEW.qty, 'sales_invoice', NEW.invoice_id, auth.uid(), 'Sale');

    -- FIFO: consume oldest available layers for this batch
    FOR v_layer IN
        SELECT *
        FROM public.inventory_cost_layers
        WHERE branch_id = NEW.branch_id
          AND medicine_id = NEW.medicine_id
          AND batch_id = NEW.batch_id
          AND remaining_qty > 0
        ORDER BY received_at, created_at, id
        FOR UPDATE
    LOOP
        EXIT WHEN v_needed <= 0;

        v_take := LEAST(v_needed, v_layer.remaining_qty);

        UPDATE public.inventory_cost_layers
        SET remaining_qty = remaining_qty - v_take
        WHERE id = v_layer.id;

        INSERT INTO public.inventory_sale_allocations (
            branch_id,
            sales_item_id,
            cost_layer_id,
            qty,
            unit_cost,
            total_cost
        )
        VALUES (
            NEW.branch_id,
            NEW.id,
            v_layer.id,
            v_take,
            v_layer.unit_cost,
            CASE
                WHEN v_layer.unit_cost IS NULL THEN NULL
                ELSE ROUND(v_take * v_layer.unit_cost, 6)
            END
        );

        v_needed := v_needed - v_take;
    END LOOP;

    -- Fail the sale if FIFO stock cannot cover the full quantity.
    IF v_needed > 0 THEN
        RAISE EXCEPTION
            'Insufficient FIFO cost-layer stock for sale. Unallocated base quantity: %',
            v_needed;
    END IF;

    RETURN NEW;
END;
$function$

returns text | SECURITY DEFINER | grants: authenticated,postgres,service_role
CREATE OR REPLACE FUNCTION public.set_batch_stock_status(p_batch uuid, p_status text, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE b public.medicine_batches%ROWTYPE; v_branch uuid := public.my_branch_id();
BEGIN
  IF COALESCE(public.my_role(), '') NOT IN ('super_admin','admin','pharmacist','inventory','inventory_staff') THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;
  IF p_status NOT IN ('active','blocked','recalled','damaged') THEN RAISE EXCEPTION 'Invalid stock status'; END IF;
  IF length(trim(COALESCE(p_reason, ''))) < 3 THEN RAISE EXCEPTION 'A reason is required'; END IF;
  SELECT * INTO b FROM public.medicine_batches WHERE id = p_batch AND branch_id = v_branch FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Batch not found in this branch'; END IF;
  UPDATE public.medicine_batches SET stock_status = p_status WHERE id = b.id;
  IF p_status <> 'active' THEN
    DELETE FROM public.stock_reservations WHERE batch_id = b.id;  -- open bills must re-allocate
  END IF;
  INSERT INTO public.audit_logs (branch_id, user_id, action, entity_type, entity_id, reason, before_data, after_data)
  VALUES (v_branch, auth.uid(), 'batch_stock_status_changed', 'medicine_batch', b.id::text, trim(p_reason),
          jsonb_build_object('stock_status', b.stock_status), jsonb_build_object('stock_status', p_status, 'batch_no', b.batch_no));
  RETURN p_status;
END;
$function$

