CREATE OR REPLACE FUNCTION public.set_credit_limit(p_customer uuid, p_limit numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_branch uuid := public.my_branch_id();
  v_old numeric;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if coalesce(public.my_role(),'') not in ('super_admin','admin') then
    raise exception 'Not authorised';
  end if;

  if p_limit is null or p_limit < 0 then
    raise exception 'Invalid credit limit';
  end if;

  select credit_limit into v_old
  from public.customers
  where id = p_customer
    and branch_id = v_branch
  for update;

  if not found then
    raise exception 'Customer not found in this branch';
  end if;

  update public.customers
  set credit_limit = p_limit
  where id = p_customer
    and branch_id = v_branch;

  insert into public.audit_logs
    (branch_id, user_id, action, entity_type, entity_id,
     reason, before_data, after_data)
  values
    (v_branch, auth.uid(), 'credit_limit_set', 'customer',
     p_customer::text, 'Customer credit limit updated',
     jsonb_build_object('credit_limit', v_old),
     jsonb_build_object('credit_limit', p_limit));
end;
$function$

