CREATE OR REPLACE FUNCTION public.set_held_bill_branch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if new.created_by is null then
    new.created_by := auth.uid();
  end if;

  if new.created_by <> auth.uid()
     and coalesce(public.my_role(),'') not in ('super_admin','admin') then
    raise exception 'Not authorised';
  end if;

  new.branch_id := public.my_branch_id();

  if new.branch_id is null then
    raise exception 'No active branch assigned';
  end if;

  return new;
end;
$function$

